/* Shared geometry, texture and material helpers. */
import * as THREE from 'three';
import { TOWN } from './data.js';

export const ROW_H = 0.58;
export const BASE_Y = 0.62;
export const WALL_T = 0.5;

export function makeRNG(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function buildingWorldPosition(def) {
  const th = (def.angle * Math.PI) / 180;
  return { x: TOWN.rx * Math.cos(th), z: TOWN.rz * Math.sin(th) };
}

export function buildingYaw(def) {
  const { x, z } = buildingWorldPosition(def);
  return Math.atan2(-x, -z);
}

function roundedRectShape(size, radius) {
  const s = size / 2;
  const r = Math.min(radius, s);
  const shape = new THREE.Shape();
  shape.moveTo(-s + r, -s);
  shape.lineTo(s - r, -s);
  shape.quadraticCurveTo(s, -s, s, -s + r);
  shape.lineTo(s, s - r);
  shape.quadraticCurveTo(s, s, s - r, s);
  shape.lineTo(-s + r, s);
  shape.quadraticCurveTo(-s, s, -s, s - r);
  shape.lineTo(-s, -s + r);
  shape.quadraticCurveTo(-s, -s, -s + r, -s);
  shape.closePath();
  return shape;
}

export function makeBrickGeometry() {
  const shape = roundedRectShape(1, 0.09);
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: 0.94,
    bevelEnabled: true,
    bevelSegments: 2,
    steps: 1,
    bevelSize: 0.028,
    bevelThickness: 0.028,
    curveSegments: 3,
  });
  geo.center();
  geo.computeVertexNormals();
  return geo;
}

export function makeCanvas(w, h) {
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  return { canvas, ctx: canvas.getContext('2d') };
}

export function texFromCanvas(canvas, anisotropy = 4) {
  const t = new THREE.CanvasTexture(canvas);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = anisotropy;
  t.needsUpdate = true;
  return t;
}

export function createMaterialCache() {
  const cache = new Map();
  return function material(color, opts = {}) {
    const key = `${color}|${opts.roughness ?? 0.86}|${opts.metalness ?? 0}|${opts.emissive ?? ''}|${opts.emissiveIntensity ?? 0}|${opts.transparent ?? false}|${opts.opacity ?? 1}|${opts.side ?? 0}`;
    if (cache.has(key)) return cache.get(key);
    const m = new THREE.MeshStandardMaterial({
      color: new THREE.Color(color),
      roughness: opts.roughness ?? 0.86,
      metalness: opts.metalness ?? 0,
      flatShading: opts.flat ?? false,
      transparent: opts.transparent ?? false,
      opacity: opts.opacity ?? 1,
      side: opts.side ?? THREE.FrontSide,
      emissive: opts.emissive ? new THREE.Color(opts.emissive) : 0x000000,
      emissiveIntensity: opts.emissiveIntensity ?? 0,
    });
    cache.set(key, m);
    return m;
  };
}

export function addBox(parent, w, h, d, color, matFor, x = 0, y = 0, z = 0, opts = {}) {
  const mesh = new THREE.Mesh(
    new THREE.BoxGeometry(w, h, d),
    matFor(color, opts)
  );
  mesh.position.set(x, y, z);
  if (opts.rot) mesh.rotation.set(opts.rot[0] || 0, opts.rot[1] || 0, opts.rot[2] || 0);
  mesh.castShadow = opts.castShadow !== false;
  mesh.receiveShadow = opts.receiveShadow !== false;
  parent.add(mesh);
  return mesh;
}

export function addCylinder(parent, rt, rb, h, seg, color, matFor, x = 0, y = 0, z = 0, opts = {}) {
  const mesh = new THREE.Mesh(
    new THREE.CylinderGeometry(rt, rb, h, seg),
    matFor(color, opts)
  );
  mesh.position.set(x, y, z);
  if (opts.rot) mesh.rotation.set(opts.rot[0] || 0, opts.rot[1] || 0, opts.rot[2] || 0);
  mesh.castShadow = opts.castShadow !== false;
  mesh.receiveShadow = opts.receiveShadow !== false;
  parent.add(mesh);
  return mesh;
}

export function makeSignTexture(title, subtitle, opts = {}) {
  const { canvas, ctx } = makeCanvas(opts.w || 512, opts.h || 220);
  const bg = opts.bg || '#f8ecd7';
  const fg = opts.fg || '#2b4552';
  ctx.fillStyle = bg;
  ctx.beginPath();
  const r = 16;
  ctx.roundRect(4, 4, canvas.width - 8, canvas.height - 8, r);
  ctx.fill();
  ctx.strokeStyle = opts.border || 'rgba(70,58,45,.35)';
  ctx.lineWidth = 6;
  ctx.stroke();
  if (opts.brickColor) {
    const bw = 76, bh = 36;
    const bx = 28, by = 26;
    ctx.fillStyle = opts.brickColor;
    ctx.beginPath();
    ctx.roundRect(bx, by, bw, bh, 8);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.28)';
    ctx.beginPath();
    ctx.roundRect(bx + 6, by + 5, bw - 12, 8, 4);
    ctx.fill();
  }
  ctx.fillStyle = fg;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `600 ${opts.titleSize || 52}px Fredoka, "Trebuchet MS", sans-serif`;
  ctx.fillText(title, canvas.width / 2, opts.subtitle ? canvas.height * 0.44 : canvas.height * 0.52);
  if (subtitle) {
    ctx.font = `700 ${opts.subSize || 24}px Nunito, "Segoe UI", sans-serif`;
    ctx.fillStyle = opts.subColor || 'rgba(50,64,70,.63)';
    ctx.fillText(subtitle, canvas.width / 2, canvas.height * 0.72);
  }
  return { canvas, ctx, texture: texFromCanvas(canvas) };
}

export function drawSignBoard(texture, ctx, canvas, title, subtitle) {
  // helper used for live-updating construction signs
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#f8ecd7';
  ctx.beginPath();
  ctx.roundRect(4, 4, canvas.width - 8, canvas.height - 8, 18);
  ctx.fill();
  ctx.strokeStyle = 'rgba(92,70,50,.35)';
  ctx.lineWidth = 7;
  ctx.stroke();
  ctx.fillStyle = '#2b4552';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = '600 58px Fredoka, "Trebuchet MS", sans-serif';
  ctx.fillText(title, canvas.width / 2, 76);
  ctx.font = '800 28px Nunito, "Segoe UI", sans-serif';
  ctx.fillStyle = 'rgba(50,64,70,.55)';
  ctx.fillText(subtitle, canvas.width / 2, 142);
  texture.needsUpdate = true;
}

/* The town environment: sky, ground, paths, plaza, greenery and small props. */
import * as THREE from 'three';
import { BUILDINGS, TOWN } from './data.js';
import { makeRNG, buildingWorldPosition, makeCanvas, texFromCanvas, addBox, addCylinder } from './gfx.js';

const TAU = Math.PI * 2;

function angleDiff(a, b) {
  let d = (a - b) % TAU;
  if (d > Math.PI) d -= TAU;
  if (d < -Math.PI) d += TAU;
  return d;
}

export class Environment {
  constructor(scene, quality, matFor, brickGeo) {
    this.scene = scene;
    this.quality = quality;
    this.matFor = matFor;
    this.brickGeo = brickGeo;
    this.rng = makeRNG(778811);
    this.time = 0;
    this.clouds = [];
    this.birds = [];
    this.smoke = [];
    this.fountainParticles = null;
    this.buildingSpots = BUILDINGS.map((def) => {
      const p = buildingWorldPosition(def);
      return { x: p.x, z: p.z, r: Math.max(def.w, def.d) };
    });
    this.group = new THREE.Group();
    this.group.name = 'environment';
    scene.add(this.group);
  }

  isPaved(x, z) {
    const r = Math.hypot(x, z);
    if (r < TOWN.plazaR + 0.8) return true;
    if (Math.abs(r - TOWN.ringR) < TOWN.ringWidth / 2 + 1.2) return true;
    if (Math.abs(x) < 3.0 && z > 10 && z < 47) return true;
    const phi = Math.atan2(z, x);
    for (const b of BUILDINGS) {
      const a = (b.angle * Math.PI) / 180;
      if (Math.abs(angleDiff(phi, a)) * r < 3.2 && r > 9 && r < TOWN.ringR + 3.5) return true;
    }
    return false;
  }

  nearBuilding(x, z, pad = 5) {
    for (const s of this.buildingSpots) {
      if (Math.hypot(x - s.x, z - s.z) < s.r / 2 + pad) return true;
    }
    return false;
  }

  isFreeGround(x, z, pad = 0) {
    const r = Math.hypot(x, z);
    if (r > 58) return false;
    if (this.isPaved(x, z)) return false;
    if (this.nearBuilding(x, z, 4 + pad)) return false;
    return true;
  }

  build() {
    this.createSky();
    this.createDistantLand();
    this.createGround();
    this.createPaths();
    this.createPlaza();
    this.createTrees();
    this.createFlowers();
    this.createRocks();
    this.createLamps();
    this.createEntrance();
    this.createClouds();
    this.createBirds();
    return this;
  }

  /* ---------------- sky ---------------- */
  createSky() {
    const skyGeo = new THREE.SphereGeometry(280, 32, 18);
    const skyMat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: {
        top: { value: new THREE.Color('#8fcfe6') },
        mid: { value: new THREE.Color('#c9e6ea') },
        horizon: { value: new THREE.Color('#ffe4bf') },
        low: { value: new THREE.Color('#f6cda5') },
        sunDir: { value: new THREE.Vector3(-0.52, 0.42, 0.55).normalize() },
      },
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        varying vec3 vDir;
        uniform vec3 top; uniform vec3 mid; uniform vec3 horizon; uniform vec3 low; uniform vec3 sunDir;
        void main() {
          float h = clamp(vDir.y, -0.2, 1.0);
          vec3 col = mix(low, horizon, smoothstep(-0.12, 0.12, h));
          col = mix(col, mid, smoothstep(0.08, 0.42, h));
          col = mix(col, top, smoothstep(0.38, 0.95, h));
          float sun = pow(max(dot(normalize(vDir), normalize(sunDir)), 0.0), 120.0);
          float glow = pow(max(dot(normalize(vDir), normalize(sunDir)), 0.0), 7.0);
          col += vec3(1.0, 0.83, 0.58) * sun * 0.9;
          col += vec3(1.0, 0.72, 0.46) * glow * 0.10;
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    });
    const sky = new THREE.Mesh(skyGeo, skyMat);
    this.scene.add(sky);

    // soft sun sprite
    const { canvas, ctx } = makeCanvas(256, 256);
    const grad = ctx.createRadialGradient(128, 128, 0, 128, 128, 128);
    grad.addColorStop(0, 'rgba(255,247,214,1)');
    grad.addColorStop(0.22, 'rgba(255,228,165,.9)');
    grad.addColorStop(0.55, 'rgba(255,210,150,.25)');
    grad.addColorStop(1, 'rgba(255,200,140,0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, 256, 256);
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: texFromCanvas(canvas), transparent: true, depthWrite: false, fog: false, blending: THREE.AdditiveBlending,
    }));
    sprite.position.set(-95, 72, 100);
    sprite.scale.set(80, 80, 1);
    this.scene.add(sprite);

    this.scene.background = new THREE.Color('#f7ddc1');
    this.scene.fog = new THREE.Fog(0xf6ddc3, 72, 185);
  }

  /* ---------------- distant hills & forest ---------------- */
  createDistantLand() {
    const colors = ['#c9a9c9', '#d8b3c7', '#b8c9a4', '#d8c0a3', '#b7a9cd', '#c7b6c1'];
    for (let i = 0; i < 14; i++) {
      const a = (i / 14) * TAU + this.rng() * 0.18;
      const r = 72 + this.rng() * 26;
      const geo = new THREE.IcosahedronGeometry(1, 0);
      const m = new THREE.Mesh(geo, this.matFor(colors[i % colors.length], { roughness: 1, flat: true }));
      m.position.set(Math.cos(a) * r, -4 - this.rng() * 5, Math.sin(a) * r);
      m.scale.set(16 + this.rng() * 18, 9 + this.rng() * 14, 15 + this.rng() * 16);
      m.rotation.set(this.rng(), this.rng() * TAU, this.rng());
      m.receiveShadow = false;
      m.castShadow = false;
      this.scene.add(m);
    }

    // distant pine forest ring (two instanced meshes)
    const pineCount = 110;
    const pineGeo = new THREE.ConeGeometry(1, 3.2, 6);
    pineGeo.translate(0, 1.6, 0);
    const pineMat = new THREE.MeshStandardMaterial({ roughness: 1, flatShading: true });
    const pines = new THREE.InstancedMesh(pineGeo, pineMat, pineCount);
    const m4 = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const colors = ['#6f9c72', '#7fa87b', '#5f8e69', '#8db482'];
    for (let i = 0; i < pineCount; i++) {
      const a = this.rng() * TAU;
      const r = 48 + this.rng() * 30;
      const s = 2.2 + this.rng() * 3.2;
      q.setFromEuler(new THREE.Euler(0, this.rng() * TAU, 0));
      m4.compose(new THREE.Vector3(Math.cos(a) * r, 0, Math.sin(a) * r), q, new THREE.Vector3(s, s * (1.4 + this.rng() * 0.7), s));
      pines.setMatrixAt(i, m4);
      pines.setColorAt(i, new THREE.Color(colors[i % colors.length]));
    }
    pines.castShadow = false;
    pines.receiveShadow = true;
    this.scene.add(pines);

    const trunkGeo = new THREE.CylinderGeometry(0.18, 0.28, 1.0, 5);
    trunkGeo.translate(0, 0.5, 0);
    const trunks = new THREE.InstancedMesh(trunkGeo, this.matFor('#8c6654', { roughness: 1 }), pineCount);
    for (let i = 0; i < pineCount; i++) {
      const a = this.rng() * TAU;
      const r = 48 + this.rng() * 30;
      const s = 2.2 + this.rng() * 3.2;
      m4.compose(new THREE.Vector3(Math.cos(a) * r, 0, Math.sin(a) * r), q, new THREE.Vector3(s, s, s));
      trunks.setMatrixAt(i, m4);
    }
    trunks.castShadow = false;
    this.scene.add(trunks);
  }

  /* ---------------- ground ---------------- */
  createGround() {
    const geo = new THREE.PlaneGeometry(220, 220, 78, 78);
    geo.rotateX(-Math.PI / 2);
    const pos = geo.attributes.position;
    const colors = [];
    const c1 = new THREE.Color('#a8ca8b');
    const c2 = new THREE.Color('#93bb7d');
    const c3 = new THREE.Color('#bad694');
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i), z = pos.getZ(i);
      const n = Math.sin(x * 0.09 + Math.cos(z * 0.07)) * 0.5 + Math.sin((x + z) * 0.045) * 0.35 + Math.sin(z * 0.17) * 0.15;
      const c = n > 0.32 ? c3 : n < -0.3 ? c2 : c1;
      const mixC = c.clone().offsetHSL((this.rng() - 0.5) * 0.012, (this.rng() - 0.5) * 0.03, (this.rng() - 0.5) * 0.035);
      colors.push(mixC.r, mixC.g, mixC.b);
      // very gentle outer swells, kept flat under the town
      const r = Math.hypot(x, z);
      pos.setY(i, r > 52 ? (Math.sin(x * 0.07) * Math.cos(z * 0.06)) * 1.2 : 0);
    }
    geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    geo.computeVertexNormals();
    const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1, metalness: 0 });
    const ground = new THREE.Mesh(geo, mat);
    ground.receiveShadow = true;
    ground.castShadow = false;
    this.scene.add(ground);

    // soft dirt patch under the town edge
    const dirt = new THREE.Mesh(
      new THREE.CircleGeometry(36, 48),
      new THREE.MeshStandardMaterial({ color: '#b6c78c', roughness: 1, transparent: true, opacity: 0.32 })
    );
    dirt.rotation.x = -Math.PI / 2;
    dirt.position.y = 0.005;
    this.scene.add(dirt);
  }

  /* ---------------- paths ---------------- */
  createPaths() {
    const pavers = [];
    const add = (x, z, rot, color, sx = 1.16, sz = 1.16) => pavers.push({ x, z, rot, color, sx, sz });
    const palette = ['#f3e3ca', '#ecd7b7', '#f8ecd8', '#e7cfae', '#f0ddc0'];
    const pick = () => palette[Math.floor(this.rng() * palette.length)];

    // ring road
    const ringSteps = Math.floor((TAU * TOWN.ringR) / 0.9);
    for (let i = 0; i < ringSteps; i++) {
      const a = (i / ringSteps) * TAU;
      const cos = Math.cos(a), sin = Math.sin(a);
      for (const off of [-1.62, -0.54, 0.54, 1.62]) {
        const jitter = (this.rng() - 0.5) * 0.1;
        add(cos * (TOWN.ringR + off) + (this.rng() - 0.5) * 0.07,
            sin * (TOWN.ringR + off) + (this.rng() - 0.5) * 0.07,
            a + Math.PI / 2 + jitter, pick());
      }
    }

    // spokes to each building
    for (const b of BUILDINGS) {
      const a = (b.angle * Math.PI) / 180;
      const cos = Math.cos(a), sin = Math.sin(a);
      for (let r = TOWN.plazaR + 0.4; r < TOWN.ringR + 2.6; r += 0.92) {
        for (const off of [-1.05, 0, 1.05]) {
          add(cos * r + Math.cos(a + Math.PI / 2) * off, sin * r + Math.sin(a + Math.PI / 2) * off,
              a + (this.rng() - 0.5) * 0.08, pick());
        }
      }
    }

    // south entrance
    for (let z = 10.5; z < 47; z += 0.95) {
      for (const x of [-1.65, -0.55, 0.55, 1.65]) {
        add(x + (this.rng() - 0.5) * 0.05, z, (this.rng() - 0.5) * 0.09, pick());
      }
    }

    const geo = new THREE.BoxGeometry(1, 0.09, 1);
    const mat = new THREE.MeshStandardMaterial({ roughness: 0.95, metalness: 0 });
    const mesh = new THREE.InstancedMesh(geo, mat, pavers.length);
    const m4 = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const e = new THREE.Euler();
    pavers.forEach((p, i) => {
      e.set(0, p.rot, 0);
      q.setFromEuler(e);
      m4.compose(new THREE.Vector3(p.x, 0.045, p.z), q, new THREE.Vector3(p.sx, 1, p.sz));
      mesh.setMatrixAt(i, m4);
      mesh.setColorAt(i, new THREE.Color(p.color));
    });
    mesh.receiveShadow = true;
    mesh.castShadow = false;
    this.scene.add(mesh);
    this.paverMesh = mesh;

    // dark outer curb ring
    const curb = new THREE.Mesh(
      new THREE.RingGeometry(TOWN.ringR + 2.42, TOWN.ringR + 2.78, 96),
      new THREE.MeshStandardMaterial({ color: '#cdb190', roughness: 1 })
    );
    curb.rotation.x = -Math.PI / 2;
    curb.position.y = 0.05;
    curb.receiveShadow = true;
    this.scene.add(curb);
  }

  /* ---------------- plaza ---------------- */
  createPlaza() {
    const { canvas, ctx } = makeCanvas(1024, 1024);
    ctx.fillStyle = '#eedbc1';
    ctx.fillRect(0, 0, 1024, 1024);
    const shades = ['#f2e2ca', '#ead7b9', '#f7ead5', '#e5cdaa', '#f0dcc0'];
    const n = 13;
    const step = 1024 / n;
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        ctx.fillStyle = shades[(i * 3 + j * 5 + Math.floor(this.rng() * 5)) % shades.length];
        ctx.fillRect(i * step + 2, j * step + 2, step - 4, step - 4);
      }
    }
    // concentric inlay
    ctx.strokeStyle = 'rgba(155,122,96,.22)';
    ctx.lineWidth = 10;
    [210, 300, 390].forEach((r) => {
      ctx.beginPath();
      ctx.arc(512, 512, r, 0, TAU);
      ctx.stroke();
    });
    ctx.strokeStyle = 'rgba(255,250,235,.35)';
    ctx.lineWidth = 3;
    [230, 320, 410].forEach((r) => {
      ctx.beginPath();
      ctx.arc(512, 512, r, 0, TAU);
      ctx.stroke();
    });
    const plazaTex = texFromCanvas(canvas, 8);
    const circle = new THREE.Mesh(
      new THREE.CircleGeometry(TOWN.plazaR + 0.6, 72),
      new THREE.MeshStandardMaterial({ map: plazaTex, roughness: 0.92 })
    );
    circle.rotation.x = -Math.PI / 2;
    circle.position.y = 0.055;
    circle.receiveShadow = true;
    this.scene.add(circle);

    const border = new THREE.Mesh(
      new THREE.RingGeometry(TOWN.plazaR + 0.58, TOWN.plazaR + 1.35, 80),
      new THREE.MeshStandardMaterial({ color: '#d8bf9f', roughness: 1 })
    );
    border.rotation.x = -Math.PI / 2;
    border.position.y = 0.05;
    border.receiveShadow = true;
    this.scene.add(border);

    // fountain
    const fg = new THREE.Group();
    fg.position.set(0, 0, 0);
    const stone = '#cbb3a0';
    const stoneDark = '#b79d89';
    addCylinder(fg, 3.25, 3.5, 0.6, 28, stone, this.matFor, 0, 0.3, 0, { roughness: 0.95 });
    const rim = new THREE.Mesh(new THREE.TorusGeometry(3.22, 0.17, 8, 32), this.matFor('#e0c9b4', { roughness: 0.9 }));
    rim.rotation.x = Math.PI / 2;
    rim.position.y = 0.62;
    rim.castShadow = true;
    rim.receiveShadow = true;
    fg.add(rim);
    const water = new THREE.Mesh(
      new THREE.CylinderGeometry(2.98, 2.98, 0.08, 32),
      new THREE.MeshStandardMaterial({ color: '#9bdde6', roughness: 0.18, metalness: 0.08, transparent: true, opacity: 0.82 })
    );
    water.position.y = 0.55;
    water.receiveShadow = true;
    fg.add(water);
    this.fountainWater = water;
    addCylinder(fg, 0.45, 0.68, 1.5, 12, stoneDark, this.matFor, 0, 1.3, 0);
    addCylinder(fg, 1.55, 1.05, 0.24, 20, '#e0c9b4', this.matFor, 0, 2.05, 0);
    addCylinder(fg, 0.22, 0.32, 0.5, 10, stone, this.matFor, 0, 2.4, 0);
    const topBall = new THREE.Mesh(new THREE.SphereGeometry(0.24, 10, 8), this.matFor('#f2e0c7', { roughness: 0.8 }));
    topBall.position.y = 2.72;
    topBall.castShadow = true;
    fg.add(topBall);
    this.scene.add(fg);
    this.fountain = fg;

    // fountain particles
    const count = 90;
    const positions = new Float32Array(count * 3);
    const vel = [];
    for (let i = 0; i < count; i++) {
      positions[i * 3] = 0; positions[i * 3 + 1] = 2.75; positions[i * 3 + 2] = 0;
      const a = Math.random() * TAU;
      const sp = 0.35 + Math.random() * 0.9;
      vel.push({ x: Math.cos(a) * sp * 0.35, y: 1.2 + Math.random() * 1.1, z: Math.sin(a) * sp * 0.35 });
    }
    const pg = new THREE.BufferGeometry();
    pg.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const pCanvas = makeCanvas(64, 64);
    const pctx = pCanvas.ctx;
    const pg2 = pctx.createRadialGradient(32, 32, 0, 32, 32, 32);
    pg2.addColorStop(0, 'rgba(255,255,255,.95)');
    pg2.addColorStop(0.45, 'rgba(190,240,245,.8)');
    pg2.addColorStop(1, 'rgba(190,240,245,0)');
    pctx.fillStyle = pg2;
    pctx.fillRect(0, 0, 64, 64);
    const points = new THREE.Points(pg, new THREE.PointsMaterial({
      color: 0xd8f8fb, size: 0.16, transparent: true, opacity: 0.9, depthWrite: false,
      map: texFromCanvas(pCanvas.canvas), blending: THREE.AdditiveBlending,
    }));
    points.frustumCulled = false;
    this.scene.add(points);
    this.fountainParticles = { points, positions, vel, count };

    // benches
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU + Math.PI / 4;
      this.createBench(Math.cos(a) * 7.2, Math.sin(a) * 7.2, -a + Math.PI / 2);
    }

    // flower beds at the plaza corners
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU + Math.PI / 8;
      const x = Math.cos(a) * 9.2, z = Math.sin(a) * 9.2;
      const bed = new THREE.Mesh(
        new THREE.CylinderGeometry(1.35, 1.45, 0.24, 16),
        this.matFor('#c8ae90', { roughness: 1 })
      );
      bed.position.set(x, 0.12, z);
      bed.receiveShadow = true;
      bed.castShadow = true;
      this.scene.add(bed);
      const soil = new THREE.Mesh(new THREE.CylinderGeometry(1.16, 1.16, 0.26, 16), this.matFor('#7d6049', { roughness: 1 }));
      soil.position.set(x, 0.15, z);
      this.scene.add(soil);
      for (let k = 0; k < 12; k++) {
        const fa = Math.random() * TAU, fr = Math.random() * 0.9;
        const flower = new THREE.Mesh(
          new THREE.SphereGeometry(0.09 + Math.random() * 0.06, 5, 4),
          this.matFor(['#f49bb5', '#f7d36c', '#f7f2e2', '#c6a3dc'][k % 4], { roughness: 0.8 })
        );
        flower.position.set(x + Math.cos(fa) * fr, 0.42 + Math.random() * 0.12, z + Math.sin(fa) * fr);
        this.scene.add(flower);
      }
    }
  }

  createBench(x, z, rot) {
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = rot;
    const wood = '#a87957';
    addBox(g, 2.2, 0.16, 0.62, wood, this.matFor, 0, 0.78, 0);
    addBox(g, 2.2, 0.7, 0.13, wood, this.matFor, 0, 1.08, -0.26);
    addBox(g, 0.13, 0.8, 0.5, '#6f5b4d', this.matFor, -0.9, 0.4, 0);
    addBox(g, 0.13, 0.8, 0.5, '#6f5b4d', this.matFor, 0.9, 0.4, 0);
    this.scene.add(g);
  }

  /* ---------------- greenery ---------------- */
  createTrees() {
    const spots = [];
    let guard = 0;
    while (spots.length < 30 && guard++ < 500) {
      const a = this.rng() * TAU;
      const r = 37 + this.rng() * 14;
      const x = Math.cos(a) * r, z = Math.sin(a) * r;
      if (this.isPaved(x, z) || this.nearBuilding(x, z, 6.5)) continue;
      if (spots.some((s) => Math.hypot(s.x - x, s.z - z) < 4.6)) continue;
      spots.push({ x, z, r });
    }
    spots.forEach((s, i) => {
      const type = i % 5 === 0 ? 'blossom' : i % 7 === 0 ? 'pine' : 'leafy';
      this.createTree(s.x, s.z, type, 0.85 + this.rng() * 0.65);
    });

    // a couple of special trees close to the plaza
    this.createTree(-16.5, 13.5, 'blossom', 1.25);
    this.createTree(17.5, 15.5, 'leafy', 1.1);
    this.createTree(-15.5, -16.5, 'blossom', 1.0);

    // bushes
    for (let i = 0; i < 22; i++) {
      const a = this.rng() * TAU;
      const r = 14 + this.rng() * 24;
      const x = Math.cos(a) * r, z = Math.sin(a) * r;
      if (!this.isFreeGround(x, z, 1.5)) continue;
      const bush = new THREE.Mesh(
        new THREE.IcosahedronGeometry(0.65 + this.rng() * 0.55, 0),
        this.matFor(['#7cae72', '#8cbc7b', '#6da267', '#a4c98d'][i % 4], { roughness: 1, flat: true })
      );
      bush.position.set(x, 0.45 + this.rng() * 0.15, z);
      bush.scale.y = 0.7 + this.rng() * 0.3;
      bush.rotation.y = this.rng() * TAU;
      bush.castShadow = true;
      bush.receiveShadow = true;
      this.scene.add(bush);
    }
  }

  createTree(x, z, type, scale = 1) {
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = this.rng() * TAU;
    if (type === 'pine') {
      addCylinder(g, 0.14, 0.22, 1.2, 6, '#8a624d', this.matFor, 0, 0.6, 0);
      const greens = ['#5f8f68', '#6b9d70', '#54835f'];
      for (let i = 0; i < 3; i++) {
        const cone = new THREE.Mesh(
          new THREE.ConeGeometry(1.35 - i * 0.3, 1.7, 7),
          this.matFor(greens[i], { roughness: 1, flat: true })
        );
        cone.position.y = 1.7 + i * 0.95;
        cone.castShadow = true;
        cone.receiveShadow = true;
        g.add(cone);
      }
    } else {
      addCylinder(g, 0.16, 0.28, 1.6, 7, '#8c6654', this.matFor, 0, 0.8, 0, { roughness: 1 });
      const leaf = type === 'blossom' ? ['#f2a9c4', '#f5b8cf', '#e99ab9'] : ['#78b371', '#86c07e', '#6da567'];
      for (let i = 0; i < 3; i++) {
        const blob = new THREE.Mesh(
          new THREE.IcosahedronGeometry(0.95 + this.rng() * 0.35, 0),
          this.matFor(leaf[i], { roughness: 1, flat: true })
        );
        blob.position.set((this.rng() - 0.5) * 1.1, 2.35 + i * 0.5, (this.rng() - 0.5) * 1.1);
        blob.scale.set(1.05, 0.92, 1.05);
        blob.castShadow = true;
        blob.receiveShadow = true;
        g.add(blob);
      }
      if (type === 'blossom') {
        const extra = new THREE.Mesh(new THREE.IcosahedronGeometry(0.65, 0), this.matFor('#f6c3d8', { roughness: 1, flat: true }));
        extra.position.set(0.85, 2.5, 0.4);
        extra.castShadow = true;
        g.add(extra);
      }
    }
    g.scale.setScalar(scale);
    this.scene.add(g);
  }

  createFlowers() {
    // grass tufts
    const grassCount = 420;
    const grassGeo = new THREE.ConeGeometry(0.055, 0.5, 3);
    grassGeo.translate(0, 0.25, 0);
    const grass = new THREE.InstancedMesh(grassGeo, new THREE.MeshStandardMaterial({ roughness: 1, flatShading: true }), grassCount);
    const m4 = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const e = new THREE.Euler();
    let gi = 0, guard = 0;
    while (gi < grassCount && guard++ < 4000) {
      const a = this.rng() * TAU;
      const r = 12 + this.rng() * 42;
      const x = Math.cos(a) * r, z = Math.sin(a) * r;
      if (!this.isFreeGround(x, z, 0.5)) continue;
      e.set((this.rng() - 0.5) * 0.2, this.rng() * TAU, (this.rng() - 0.5) * 0.2);
      q.setFromEuler(e);
      const s = 0.7 + this.rng() * 1.1;
      m4.compose(new THREE.Vector3(x, 0.02, z), q, new THREE.Vector3(s, s, s));
      grass.setMatrixAt(gi, m4);
      grass.setColorAt(gi, new THREE.Color(['#7fb677', '#8cc481', '#6fa96b', '#9ccb8a'][gi % 4]));
      gi++;
    }
    grass.count = gi;
    grass.receiveShadow = true;
    this.scene.add(grass);

    // flower heads with tiny stems
    const flowerCount = 260;
    const stemGeo = new THREE.CylinderGeometry(0.012, 0.015, 0.34, 3);
    stemGeo.translate(0, 0.17, 0);
    const stems = new THREE.InstancedMesh(stemGeo, new THREE.MeshStandardMaterial({ color: '#6b9d63', roughness: 1 }), flowerCount);
    const headGeo = new THREE.SphereGeometry(0.075, 5, 4);
    const heads = new THREE.InstancedMesh(headGeo, new THREE.MeshStandardMaterial({ roughness: 0.8 }), flowerCount);
    const petalColors = ['#f7f2e3', '#f6a9c0', '#f7d36c', '#c7a6de', '#f18f85', '#9ed3e8'];
    let fi = 0; guard = 0;
    while (fi < flowerCount && guard++ < 4000) {
      const a = this.rng() * TAU;
      const r = 12 + this.rng() * 40;
      const x = Math.cos(a) * r, z = Math.sin(a) * r;
      if (!this.isFreeGround(x, z, 0.5)) continue;
      const s = 0.8 + this.rng() * 0.9;
      m4.compose(new THREE.Vector3(x, 0.02, z), q.identity(), new THREE.Vector3(s, s, s));
      stems.setMatrixAt(fi, m4);
      m4.compose(new THREE.Vector3(x, 0.2 + 0.34 * s, z), q, new THREE.Vector3(s, s, s));
      heads.setMatrixAt(fi, m4);
      heads.setColorAt(fi, new THREE.Color(petalColors[fi % petalColors.length]));
      fi++;
    }
    stems.count = fi; heads.count = fi;
    this.scene.add(stems);
    this.scene.add(heads);
  }

  createRocks() {
    const colors = ['#d3a7bd', '#c3a5c9', '#d9b3a6', '#b7a9c8'];
    for (let i = 0; i < 15; i++) {
      const a = this.rng() * TAU;
      const r = 40 + this.rng() * 20;
      const rock = new THREE.Mesh(
        new THREE.DodecahedronGeometry(0.7 + this.rng() * 1.8, 0),
        this.matFor(colors[i % colors.length], { roughness: 1, flat: true })
      );
      rock.position.set(Math.cos(a) * r, 0.3 + this.rng() * 0.4, Math.sin(a) * r);
      rock.scale.set(1 + this.rng(), 0.6 + this.rng() * 0.6, 1 + this.rng() * 0.8);
      rock.rotation.set(this.rng(), this.rng() * TAU, this.rng());
      rock.castShadow = true;
      rock.receiveShadow = true;
      this.scene.add(rock);
    }
  }

  /* ---------------- lamps, entrance, sky decor ---------------- */
  createLamps() {
    for (let i = 0; i < 7; i++) {
      const a = (i / 7) * TAU + 0.23;
      this.createLamp(Math.cos(a) * 13.4, Math.sin(a) * 13.4, -a + Math.PI / 2);
    }
    this.createLamp(-4.2, 34, 0);
    this.createLamp(4.2, 34, 0);
  }

  createLamp(x, z, rot) {
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = rot;
    addCylinder(g, 0.11, 0.16, 2.45, 8, '#4c5d5b', this.matFor, 0, 1.22, 0);
    addCylinder(g, 0.22, 0.27, 0.18, 8, '#4c5d5b', this.matFor, 0, 0.09, 0);
    addBox(g, 0.52, 0.08, 0.08, '#4c5d5b', this.matFor, 0.18, 2.4, 0);
    const globe = new THREE.Mesh(
      new THREE.SphereGeometry(0.24, 10, 8),
      new THREE.MeshStandardMaterial({ color: '#fff0c7', emissive: '#ffd98c', emissiveIntensity: 1.15, roughness: 0.3 })
    );
    globe.position.set(0.4, 2.3, 0);
    g.add(globe);
    // little cap
    const cap = new THREE.Mesh(new THREE.ConeGeometry(0.32, 0.22, 8), this.matFor('#4c5d5b', { roughness: 0.8 }));
    cap.position.set(0.4, 2.55, 0);
    g.add(cap);
    g.traverse((o) => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
    this.scene.add(g);
  }

  createEntrance() {
    const g = new THREE.Group();
    g.position.set(0, 0, 38.5);
    const wood = '#b98961';
    const cream = '#f3e3c8';
    addCylinder(g, 0.28, 0.34, 4.3, 8, wood, this.matFor, -3.6, 2.15, 0);
    addCylinder(g, 0.28, 0.34, 4.3, 8, wood, this.matFor, 3.6, 2.15, 0);
    addBox(g, 8.1, 0.46, 0.36, wood, this.matFor, 0, 4.25, 0);
    addBox(g, 7.0, 0.16, 0.22, cream, this.matFor, 0, 4.0, 0.08);
    const signTex = texFromCanvas((() => {
      const { canvas, ctx } = makeCanvas(512, 160);
      ctx.fillStyle = '#f7e8cf';
      ctx.fillRect(0, 0, 512, 160);
      ctx.strokeStyle = 'rgba(82,61,45,.35)';
      ctx.lineWidth = 8;
      ctx.strokeRect(5, 5, 502, 150);
      ctx.fillStyle = '#36505a';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = '600 66px Fredoka, "Trebuchet MS", sans-serif';
      ctx.fillText('MAPLE HOLLOW', 256, 64);
      ctx.font = '800 24px Nunito, "Segoe UI", sans-serif';
      ctx.fillStyle = 'rgba(54,80,90,.6)';
      ctx.fillText('a small town · put back together', 256, 118);
      return canvas;
    })());
    const sign = new THREE.Mesh(
      new THREE.PlaneGeometry(5.5, 1.72),
      new THREE.MeshBasicMaterial({ map: signTex, transparent: true })
    );
    sign.position.set(0, 3.5, 0.19);
    g.add(sign);
    // hanging flower baskets
    [-3.6, 3.6].forEach((x) => {
      const basket = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.22, 0.28, 8), this.matFor('#b0744e', { roughness: 1 }));
      basket.position.set(x, 3.35, 0);
      g.add(basket);
      for (let i = 0; i < 5; i++) {
        const f = new THREE.Mesh(new THREE.SphereGeometry(0.12, 5, 4), this.matFor(['#f4a1b8', '#f6d36b', '#f7f1df'][i % 3], { roughness: 0.8 }));
        f.position.set(x + (Math.random() - 0.5) * 0.5, 3.42 + Math.random() * 0.18, (Math.random() - 0.5) * 0.3);
        g.add(f);
      }
    });
    g.traverse((o) => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
    this.scene.add(g);
    this.entrance = g;
  }

  createClouds() {
    const cloudMat = new THREE.MeshStandardMaterial({
      color: '#fff7e8', roughness: 1, metalness: 0, flatShading: true, emissive: '#ffeed2', emissiveIntensity: 0.35, fog: false,
    });
    const geo = new THREE.SphereGeometry(1, 7, 5);
    for (let i = 0; i < 9; i++) {
      const g = new THREE.Group();
      const puffs = 3 + Math.floor(this.rng() * 3);
      for (let p = 0; p < puffs; p++) {
        const puff = new THREE.Mesh(geo, cloudMat);
        puff.position.set((p - puffs / 2) * 1.45 + this.rng() * 0.5, this.rng() * 0.7, this.rng() * 1.2);
        puff.scale.set(1.4 + this.rng() * 1.5, 0.8 + this.rng() * 0.8, 1.1 + this.rng());
        g.add(puff);
      }
      const a = this.rng() * TAU;
      const r = 55 + this.rng() * 70;
      g.position.set(Math.cos(a) * r, 28 + this.rng() * 22, Math.sin(a) * r);
      g.scale.setScalar(2.2 + this.rng() * 2.4);
      g.userData.speed = 0.35 + this.rng() * 0.5;
      this.scene.add(g);
      this.clouds.push(g);
    }
  }

  createBirds() {
    const mat = new THREE.MeshBasicMaterial({ color: '#57506a', side: THREE.DoubleSide, fog: false });
    const wingGeo = new THREE.BufferGeometry();
    wingGeo.setAttribute('position', new THREE.Float32BufferAttribute([0, 0, 0, 0.75, 0.08, 0.15, 0.15, -0.02, 0.28], 3));
    wingGeo.computeVertexNormals();
    for (let i = 0; i < 5; i++) {
      const g = new THREE.Group();
      const left = new THREE.Mesh(wingGeo, mat);
      const right = new THREE.Mesh(wingGeo, mat);
      right.scale.x = -1;
      g.add(left, right);
      g.scale.setScalar(1.5);
      g.userData = {
        radius: 22 + this.rng() * 20,
        height: 17 + this.rng() * 12,
        speed: 0.045 + this.rng() * 0.05,
        phase: this.rng() * TAU,
        left, right,
      };
      this.scene.add(g);
      this.birds.push(g);
    }
  }

  /* ---------------- update ---------------- */
  update(dt, time) {
    this.time = time;
    // fountain water
    if (this.fountainParticles) {
      const p = this.fountainParticles;
      for (let i = 0; i < p.count; i++) {
        const ix = i * 3;
        p.positions[ix] += p.vel[i].x * dt;
        p.positions[ix + 1] += p.vel[i].y * dt;
        p.positions[ix + 2] += p.vel[i].z * dt;
        p.vel[i].y -= 3.6 * dt;
        if (p.positions[ix + 1] < 0.72) {
          p.positions[ix] = 0; p.positions[ix + 1] = 2.75; p.positions[ix + 2] = 0;
          const a = Math.random() * TAU, sp = 0.35 + Math.random() * 0.9;
          p.vel[i].x = Math.cos(a) * sp * 0.35;
          p.vel[i].y = 1.2 + Math.random() * 1.1;
          p.vel[i].z = Math.sin(a) * sp * 0.35;
        }
      }
      p.points.geometry.attributes.position.needsUpdate = true;
    }
    if (this.fountainWater) this.fountainWater.rotation.y += dt * 0.07;

    for (const cloud of this.clouds) {
      cloud.position.x += cloud.userData.speed * dt;
      if (cloud.position.x > 135) cloud.position.x = -135;
    }

    for (const bird of this.birds) {
      const u = bird.userData;
      u.phase += dt * u.speed;
      bird.position.set(Math.cos(u.phase) * u.radius, u.height + Math.sin(u.phase * 3) * 0.5, Math.sin(u.phase) * u.radius);
      bird.rotation.y = -u.phase + Math.PI / 2;
      const flap = Math.sin(time * 7 + u.phase * 6) * 0.55;
      u.left.rotation.z = flap;
      u.right.rotation.z = -flap;
    }
  }

  collides(x, z, radius) {
    // fountain
    if (Math.hypot(x, z) < 3.55 + radius) return true;
    // entrance posts
    if (Math.hypot(x + 3.6, z - 38.5) < 0.42 + radius) return true;
    if (Math.hypot(x - 3.6, z - 38.5) < 0.42 + radius) return true;
    return false;
  }
}

/* Procedural brick buildings, blueprint slots, piles and completion state. */
import * as THREE from 'three';
import { BUILDINGS, PALETTES, BRICK_TYPES, brickKey, keyInfo } from './data.js';
import {
  ROW_H, BASE_Y, WALL_T, makeRNG, buildingWorldPosition, buildingYaw,
  makeCanvas, texFromCanvas, makeSignTexture, drawSignBoard, addBox, addCylinder,
} from './gfx.js';
import { addBuildingDecor } from './decor.js';

const HIDDEN = new THREE.Matrix4().compose(
  new THREE.Vector3(0, -999, 0), new THREE.Quaternion(), new THREE.Vector3(0.0001, 0.0001, 0.0001)
);
const TAU = Math.PI * 2;

function easeOutBack(t) {
  const c1 = 1.70158, c3 = c1 + 1;
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
}

export class BuildingManager {
  constructor(scene, matFor, brickGeo, quality = {}) {
    this.scene = scene;
    this.matFor = matFor;
    this.brickGeo = brickGeo;
    this.quality = quality;
    this.buildings = [];
    this.piles = [];
    this.focusId = null;
    this.focusUntil = 0;
    this.time = 0;
    this.activeId = null;
    this.active = null;
    this.decorHooks = [];
    this.onPlace = null;
    this.onComplete = null;
    this.clockHands = [];
    this.smokeEmitters = [];
    this.brickMat = new THREE.MeshStandardMaterial({ roughness: 0.74, metalness: 0.02 });
    this.ghostMat = new THREE.MeshStandardMaterial({
      color: '#8be7f7', emissive: '#2c7c94', emissiveIntensity: 0.5, transparent: true, opacity: 0.24,
      roughness: 0.35, metalness: 0.05, depthWrite: false, side: THREE.DoubleSide,
    });
    this.marker = this.createMarker();
  }

  build() {
    BUILDINGS.forEach((def, i) => this.createBuilding(def, i));
    return this;
  }

  get completedCount() {
    return this.buildings.filter((b) => b.completed).length;
  }

  get allComplete() {
    return this.completedCount === this.buildings.length;
  }

  get totalPlaced() {
    return this.buildings.reduce((a, b) => a + b.placedCount, 0);
  }

  get totalBricks() {
    return this.buildings.reduce((a, b) => a + b.slots.length, 0);
  }

  getBuilding(id) {
    return this.buildings.find((b) => b.def.id === id) || null;
  }

  /* ============================================================
     Slot generation
     ============================================================ */
  generateSlots(def, index) {
    const rng = makeRNG(1409 + index * 977);
    const pal = PALETTES[def.palette];
    const cache = new Map();
    const piece = (id) => {
      const base = pal[id] || pal.wall;
      if (!cache.has(id)) cache.set(id, { ...base, key: brickKey(base), id });
      return cache.get(id);
    };
    const slots = [];
    const add = (pieceId, dims, x, y, z, quat = null, meta = {}) => {
      const p = piece(pieceId);
      const q = quat ? quat.clone() : new THREE.Quaternion();
      const pos = new THREE.Vector3(x, y, z);
      const localMatrix = new THREE.Matrix4().compose(pos, q, new THREE.Vector3(dims[0], dims[1], dims[2]));
      slots.push({
        index: slots.length, piece: p, key: p.key, dims: [...dims], pos, quat: q,
        localMatrix, placed: false, color: p.color, meta,
      });
    };

    const wallTop = BASE_Y + def.rows * ROW_H;
    const halfW = def.w / 2, halfD = def.d / 2;
    const windows = [];
    const openingsFor = this.makeOpenings(def);

    // ---- wall courses ----
    const sides = [
      { name: 'front', axis: 'x', len: def.w, fixed: halfD - WALL_T / 2, sign: 1 },
      { name: 'back', axis: 'x', len: def.w, fixed: -halfD + WALL_T / 2, sign: -1 },
      { name: 'right', axis: 'z', len: def.d, fixed: halfW - WALL_T / 2, sign: 1 },
      { name: 'left', axis: 'z', len: def.d, fixed: -halfW + WALL_T / 2, sign: -1 },
    ];

    for (const side of sides) {
      const opens = openingsFor.filter((o) => o.side === side.name);
      const count = Math.max(2, Math.round(side.len / 1.36));
      const step = side.len / count;
      for (let row = 0; row < def.rows; row++) {
        const stagger = (row % 2) ? step * 0.5 : 0;
        for (let i = 0; i < count; i++) {
          let u = -side.len / 2 + step * (i + 0.5) + stagger;
          u = Math.max(-side.len / 2 + step / 2, Math.min(side.len / 2 - step / 2, u));
          let skip = false;
          for (const op of opens) {
            if (row >= op.row0 && row <= op.row1 && Math.abs(u - op.u) < op.w / 2 + step * 0.34) { skip = true; break; }
          }
          if (skip) continue;
          const brickLen = step - 0.035;
          const y = BASE_Y + row * ROW_H + ROW_H / 2;
          const isCorner = i === 0 || i === count - 1;
          let pid = 'wall';
          if (row === 0 || row === def.rows - 1 || isCorner) pid = 'trim';
          else if (row === 2 && (def.style === 'cottage' || def.style === 'bakery') && i % 4 === 0) pid = 'wallDeep';
          else if (rng() < 0.08) pid = 'wallDeep';
          if (def.style === 'greenhouse' && row > 0 && !isCorner && i % 3 === 1) pid = 'trim';
          const dims = side.axis === 'x'
            ? [brickLen, ROW_H - 0.04, WALL_T]
            : [WALL_T, ROW_H - 0.04, brickLen];
          const x = side.axis === 'x' ? u : side.fixed;
          const z = side.axis === 'x' ? side.fixed : u;
          add(pid, dims, x, y, z, null, { side: side.name, row });
        }
      }
    }

    // ---- windows as placeable slots ----
    for (const op of openingsFor) {
      if (op.type !== 'window') continue;
      const winH = (op.row1 - op.row0 + 1) * ROW_H - 0.1;
      const winW = Math.min(op.w, 1.65);
      const y = BASE_Y + ((op.row0 + op.row1 + 1) / 2) * ROW_H;
      const side = sides.find((s) => s.name === op.side);
      let dims, x, z;
      if (side.axis === 'x') {
        dims = [winW, winH, 0.3];
        x = op.u;
        z = side.fixed + (side.sign > 0 ? 0.03 : -0.03);
      } else {
        dims = [0.3, winH, winW];
        x = side.fixed + (side.sign > 0 ? 0.03 : -0.03);
        z = op.u;
      }
      add('glass', dims, x, y, z, null, { window: true, side: op.side });
      windows.push({ ...op, y, winH, winW, side });
    }

    // ---- gable ends ----
    if (def.roof !== 'flat') {
      const rise = def.roofRise;
      const G = Math.max(1, Math.round(rise / ROW_H));
      for (const side of [{ z: halfD - WALL_T / 2, name: 'front' }, { z: -halfD + WALL_T / 2, name: 'back' }]) {
        for (let g = 0; g < G; g++) {
          const y = wallTop + g * ROW_H + ROW_H / 2;
          const half = (def.w / 2) * (1 - g / G);
          const n = Math.max(1, Math.round((half * 2) / 1.36));
          const step = (half * 2) / n;
          for (let i = 0; i < n; i++) {
            const x = -half + step * (i + 0.5);
            let pid = 'wall';
            if (i === 0 || i === n - 1) pid = 'trim';
            else if (g === G - 1) pid = 'trim';
            add(pid, [step - 0.035, ROW_H - 0.04, WALL_T], x, y, side.z);
          }
        }
      }
    }

    // ---- roof ----
    const roofTop = def.roof === 'flat' ? wallTop + 0.25 : wallTop + def.roofRise;
    if (def.roof === 'flat') {
      for (let ix = 0; ix < 2; ix++) {
        for (let iz = 0; iz < 2; iz++) {
          add('roof', [def.w / 2 + 0.25, 0.36, def.d / 2 + 0.25], (ix - 0.5) * (def.w / 2 + 0.1), wallTop + 0.17, (iz - 0.5) * (def.d / 2 + 0.1));
        }
      }
    } else {
      const overX = 0.55, overZ = 0.6;
      const halfD2 = halfD + overZ;
      const rise = def.roadRise || def.roofRise;
      const angle = Math.atan2(rise, halfD2);
      const slopeLen = Math.hypot(rise, halfD2);
      const cols = def.w > 8 ? 3 : 2;
      const bw = (def.w + overX * 2) / cols;
      const rows = def.roofRows || 3;
      const roofPid = def.palette === 'greenhouse' ? 'roof' : 'roof';
      for (const side of [1, -1]) {
        for (let r = 0; r < rows; r++) {
          const f = (r + 0.5) / rows;
          const z = side * halfD2 * (1 - f);
          const y = wallTop + rise * f + 0.12;
          const segLen = slopeLen / rows + 0.14;
          const q = new THREE.Quaternion().setFromEuler(new THREE.Euler(side * angle, 0, 0));
          for (let c = 0; c < cols; c++) {
            const x = -def.w / 2 - overX + bw * (c + 0.5);
            let pid = roofPid;
            if (def.style === 'market' && (r + c) % 2 === 0 && pal.roofAlt) pid = 'roofAlt';
            add(pid, [bw - 0.04, 0.34, segLen], x, y, z, q, { roof: true });
          }
        }
      }
      add('roof', [def.w + overX * 2 + 0.1, 0.24, 0.55], 0, wallTop + rise + 0.22, 0, null, { roof: true, ridge: true });
    }

    return { slots, windows, wallTop, roofTop };
  }

  makeOpenings(def) {
    const list = [];
    const rows = def.rows;
    const winRows = rows >= 5 ? [2, 3] : [1, 2];
    const doorW = def.style === 'market' ? 2.35 : def.style === 'chapel' ? 1.75 : def.style === 'clocktower' ? 1.95 : 1.55;
    list.push({ side: 'front', u: 0, row0: 0, row1: 2, w: doorW, type: 'door' });
    const wx = def.w * 0.275;
    if (def.style === 'chapel') {
      list.push({ side: 'front', u: 0, row0: 3, row1: 4, w: 1.8, type: 'window' });
      list.push({ side: 'left', u: 0, row0: 1, row1: 3, w: 1.0, type: 'window' });
      list.push({ side: 'right', u: 0, row0: 1, row1: 3, w: 1.0, type: 'window' });
      return list;
    }
    if (def.style === 'clocktower') {
      list.push({ side: 'front', u: -wx, row0: 3, row1: 4, w: 1.1, type: 'window' });
      list.push({ side: 'front', u: wx, row0: 3, row1: 4, w: 1.1, type: 'window' });
      list.push({ side: 'left', u: -def.d * 0.2, row0: 2, row1: 3, w: 1.0, type: 'window' });
      list.push({ side: 'right', u: -def.d * 0.2, row0: 2, row1: 3, w: 1.0, type: 'window' });
      list.push({ side: 'back', u: -wx, row0: 2, row1: 3, w: 1.0, type: 'window' });
      list.push({ side: 'back', u: wx, row0: 2, row1: 3, w: 1.0, type: 'window' });
      return list;
    }
    if (def.style === 'greenhouse') {
      list.push({ side: 'front', u: -wx, row0: 1, row1: 2, w: 1.5, type: 'window' });
      list.push({ side: 'front', u: wx, row0: 1, row1: 2, w: 1.5, type: 'window' });
      list.push({ side: 'back', u: -wx, row0: 1, row1: 2, w: 1.5, type: 'window' });
      list.push({ side: 'back', u: wx, row0: 1, row1: 2, w: 1.5, type: 'window' });
      list.push({ side: 'left', u: -def.d * 0.2, row0: 1, row1: 2, w: 1.3, type: 'window' });
      list.push({ side: 'left', u: def.d * 0.2, row0: 1, row1: 2, w: 1.3, type: 'window' });
      list.push({ side: 'right', u: -def.d * 0.2, row0: 1, row1: 2, w: 1.3, type: 'window' });
      list.push({ side: 'right', u: def.d * 0.2, row0: 1, row1: 2, w: 1.3, type: 'window' });
      return list;
    }
    if (def.style === 'market') {
      list.push({ side: 'front', u: -wx, row0: 1, row1: 2, w: 1.2, type: 'window' });
      list.push({ side: 'front', u: wx, row0: 1, row1: 2, w: 1.2, type: 'window' });
      list.push({ side: 'back', u: -wx, row0: 1, row1: 2, w: 1.1, type: 'window' });
      list.push({ side: 'back', u: wx, row0: 1, row1: 2, w: 1.1, type: 'window' });
      list.push({ side: 'left', u: 0, row0: 1, row1: 2, w: 1.0, type: 'window' });
      list.push({ side: 'right', u: 0, row0: 1, row1: 2, w: 1.0, type: 'window' });
      return list;
    }
    // standard cottage-ish building
    list.push({ side: 'front', u: -wx, row0: winRows[0], row1: winRows[1], w: 1.1, type: 'window' });
    list.push({ side: 'front', u: wx, row0: winRows[0], row1: winRows[1], w: 1.1, type: 'window' });
    list.push({ side: 'back', u: -wx, row0: winRows[0], row1: winRows[1], w: 1.0, type: 'window' });
    list.push({ side: 'back', u: wx, row0: winRows[0], row1: winRows[1], w: 1.0, type: 'window' });
    list.push({ side: 'left', u: 0, row0: winRows[0], row1: winRows[1], w: 1.0, type: 'window' });
    list.push({ side: 'right', u: 0, row0: winRows[0], row1: winRows[1], w: 1.0, type: 'window' });
    return list;
  }

  /* ============================================================
     Building creation
     ============================================================ */
  createBuilding(def, index) {
    const rng = makeRNG(9001 + index * 331);
    const pos = buildingWorldPosition(def);
    const group = new THREE.Group();
    group.position.set(pos.x, 0, pos.z);
    group.rotation.y = buildingYaw(def);
    group.name = `building-${def.id}`;
    this.scene.add(group);

    const { slots, windows, wallTop, roofTop } = this.generateSlots(def, index);
    const b = {
      def, index, group, slots, windows, wallTop, roofTop,
      placedCount: 0, completed: false, pops: [], decor: null, decorPop: -1,
      x: pos.x, z: pos.z, yaw: group.rotation.y,
      sign: null, scaffold: null, fence: null, signGroup: null, piles: [],
      total: slots.length,
    };

    const ghost = new THREE.InstancedMesh(this.brickGeo, this.ghostMat, slots.length);
    ghost.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    ghost.frustumCulled = false;
    ghost.castShadow = false;
    ghost.receiveShadow = false;
    ghost.userData = { type: 'ghost', building: b };
    const placed = new THREE.InstancedMesh(this.brickGeo, this.brickMat, slots.length);
    placed.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    placed.frustumCulled = false;
    placed.castShadow = true;
    placed.receiveShadow = true;
    placed.userData = { type: 'placed', building: b };

    const color = new THREE.Color();
    slots.forEach((slot, i) => {
      ghost.setMatrixAt(i, slot.localMatrix);
      placed.setMatrixAt(i, HIDDEN);
      color.set(slot.piece.color);
      color.offsetHSL((rng() - 0.5) * 0.008, (rng() - 0.5) * 0.035, (rng() - 0.5) * 0.038);
      slot.instanceColor = color.clone();
      placed.setColorAt(i, slot.instanceColor);
    });
    ghost.instanceMatrix.needsUpdate = true;
    placed.instanceMatrix.needsUpdate = true;
    placed.instanceColor.needsUpdate = true;
    group.add(ghost, placed);
    b.ghost = ghost;
    b.placed = placed;

    this.buildFoundation(b);
    this.buildSite(b);
    this.buildPiles(b);
    this.buildings.push(b);
    return b;
  }

  buildFoundation(b) {
    const def = b.def;
    const pal = PALETTES[def.palette];
    const g = b.group;
    // stone site pad
    const pad = new THREE.Mesh(
      new THREE.BoxGeometry(def.w + 3.2, 0.14, def.d + 3.2),
      this.matFor('#d9c3a5', { roughness: 1 })
    );
    pad.position.y = 0.07;
    pad.receiveShadow = true;
    pad.castShadow = true;
    g.add(pad);
    // foundation
    addBox(g, def.w + 0.7, BASE_Y, def.d + 0.7, pal.base.color, this.matFor, 0, BASE_Y / 2, 0, { roughness: 1 });
    addBox(g, def.w + 1.0, 0.14, def.d + 1.0, '#b79b9b', this.matFor, 0, BASE_Y + 0.02, 0, { roughness: 1 });
    // steps
    addBox(g, 2.0, 0.16, 0.6, '#d8c2a6', this.matFor, 0, 0.08, def.d / 2 + 0.72, { roughness: 1 });
    addBox(g, 1.75, 0.3, 0.45, '#cdb49a', this.matFor, 0, 0.15, def.d / 2 + 0.5, { roughness: 1 });
    // dark doorway recess
    addBox(g, 1.42, 2.08, 0.12, '#443744', this.matFor, 0, BASE_Y + 1.04, def.d / 2 - 0.22, { roughness: 1 });
    // door frame
    const trim = PALETTES[def.palette].trim.color;
    addBox(g, 0.18, 2.35, 0.16, trim, this.matFor, -0.82, BASE_Y + 1.18, def.d / 2 + 0.01);
    addBox(g, 0.18, 2.35, 0.16, trim, this.matFor, 0.82, BASE_Y + 1.18, def.d / 2 + 0.01);
    addBox(g, 1.82, 0.2, 0.16, trim, this.matFor, 0, BASE_Y + 2.26, def.d / 2 + 0.01);

    // window frames around the openings
    const sideInfo = {
      front: { axis: 'x', fixed: def.d / 2 },
      back: { axis: 'x', fixed: -def.d / 2 },
      left: { axis: 'z', fixed: -def.w / 2 },
      right: { axis: 'z', fixed: def.w / 2 },
    };
    for (const w of b.windows) {
      const info = sideInfo[w.side];
      const cy = w.y;
      const h = w.winH;
      const ww = w.winW;
      const frameCol = def.palette === 'greenhouse' ? '#f1e6cf' : trim;
      if (info.axis === 'x') {
        const z = info.fixed + (info.fixed > 0 ? 0.03 : -0.03);
        addBox(g, 0.13, h + 0.24, 0.16, frameCol, this.matFor, w.u - ww / 2 - 0.05, cy, z);
        addBox(g, 0.13, h + 0.24, 0.16, frameCol, this.matFor, w.u + ww / 2 + 0.05, cy, z);
        addBox(g, ww + 0.24, 0.14, 0.18, frameCol, this.matFor, w.u, cy + h / 2 + 0.06, z);
        addBox(g, ww + 0.24, 0.14, 0.2, frameCol, this.matFor, w.u, cy - h / 2 - 0.06, z);
        addBox(g, ww + 0.36, 0.11, 0.32, '#cdb49a', this.matFor, w.u, cy - h / 2 - 0.18, z + (z > 0 ? 0.06 : -0.06), { roughness: 1 });
      } else {
        const x = info.fixed + (info.fixed > 0 ? 0.03 : -0.03);
        addBox(g, 0.16, h + 0.24, 0.13, frameCol, this.matFor, x, cy, w.u - ww / 2 - 0.05);
        addBox(g, 0.16, h + 0.24, 0.13, frameCol, this.matFor, x, cy, w.u + ww / 2 + 0.05);
        addBox(g, 0.18, 0.14, ww + 0.24, frameCol, this.matFor, x, cy + h / 2 + 0.06, w.u);
        addBox(g, 0.2, 0.14, ww + 0.24, frameCol, this.matFor, x, cy - h / 2 - 0.06, w.u);
        addBox(g, 0.32, 0.11, ww + 0.36, '#cdb49a', this.matFor, x + (x > 0 ? 0.06 : -0.06), cy - h / 2 - 0.18, w.u, { roughness: 1 });
      }
    }

    // loose construction rubble
    for (let i = 0; i < 7; i++) {
      const rubble = new THREE.Mesh(this.brickGeo, this.matFor(i % 2 ? pal.base.color : '#cfb6aa', { roughness: 0.9 }));
      rubble.scale.set(0.5 + Math.random() * 0.3, 0.28, 0.22);
      rubble.position.set((Math.random() - 0.5) * (def.w + 2.2), 0.14, (Math.random() - 0.5) * 2 + def.d / 2 + 1.6);
      rubble.rotation.set(Math.random() * 0.4 - 0.2, Math.random() * TAU, 0);
      rubble.castShadow = true;
      g.add(rubble);
    }
  }

  /* ---------------- scaffolding, fencing, sign ---------------- */
  buildSite(b) {
    const def = b.def;
    const g = b.group;
    const halfW = def.w / 2 + 1.8;
    const halfD = def.d / 2 + 1.8;

    // --- low construction fence ---
    const posts = [];
    const rails = [];
    const pushSide = (x1, z1, x2, z2) => {
      const len = Math.hypot(x2 - x1, z2 - z1);
      const n = Math.max(2, Math.ceil(len / 1.45));
      const rot = Math.atan2(x2 - x1, z2 - z1);
      for (let i = 0; i <= n; i++) {
        const t = i / n;
        posts.push({ x: x1 + (x2 - x1) * t, z: z1 + (z2 - z1) * t });
      }
      for (let i = 0; i < n; i++) {
        const t0 = i / n, t1 = (i + 1) / n;
        const cx = x1 + (x2 - x1) * (t0 + t1) / 2;
        const cz = z1 + (z2 - z1) * (t0 + t1) / 2;
        rails.push({ x: cx, z: cz, len: len / n, rot });
      }
    };
    pushSide(-halfW, -halfD, halfW, -halfD); // back
    pushSide(-halfW, -halfD, -halfW, halfD); // left
    pushSide(halfW, -halfD, halfW, halfD); // right
    pushSide(-halfW, halfD, -1.5, halfD); // front left
    pushSide(1.5, halfD, halfW, halfD); // front right

    const fenceGroup = new THREE.Group();
    const postGeo = new THREE.BoxGeometry(0.12, 0.98, 0.12);
    const railGeo = new THREE.BoxGeometry(1, 0.1, 0.07);
    const postMesh = new THREE.InstancedMesh(postGeo, this.matFor('#c35e70', { roughness: 0.85 }), posts.length);
    const railMesh = new THREE.InstancedMesh(railGeo, this.matFor('#d58a74', { roughness: 0.85 }), rails.length * 2);
    const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), e = new THREE.Euler();
    posts.forEach((p, i) => {
      m4.compose(new THREE.Vector3(p.x, 0.49, p.z), q.identity(), new THREE.Vector3(1, 1, 1));
      postMesh.setMatrixAt(i, m4);
    });
    rails.forEach((r, i) => {
      e.set(0, r.rot + Math.PI / 2, 0); q.setFromEuler(e);
      m4.compose(new THREE.Vector3(r.x, 0.4, r.z), q, new THREE.Vector3(r.len, 1, 1));
      railMesh.setMatrixAt(i * 2, m4);
      m4.compose(new THREE.Vector3(r.x, 0.76, r.z), q, new THREE.Vector3(r.len, 1, 1));
      railMesh.setMatrixAt(i * 2 + 1, m4);
    });
    postMesh.castShadow = true; railMesh.castShadow = true;
    fenceGroup.add(postMesh, railMesh);
    g.add(fenceGroup);
    b.fence = fenceGroup;

    // --- scaffolding ---
    const scaffold = new THREE.Group();
    const poleGeo = new THREE.CylinderGeometry(0.055, 0.065, 1, 6);
    const poles = [];
    const scHalfW = def.w / 2 + 0.65, scHalfD = def.d / 2 + 0.65;
    const H = Math.min(b.wallTop + def.roofRise * 0.35, 7.2);
    const corners = [];
    for (const x of [-scHalfW, scHalfW]) for (const z of [-scHalfD, scHalfD]) corners.push({ x, z });
    for (const x of [0]) for (const z of [-scHalfD, scHalfD]) corners.push({ x, z });
    for (const z of [0]) for (const x of [-scHalfW, scHalfW]) corners.push({ x, z });
    const poleMesh = new THREE.InstancedMesh(poleGeo, this.matFor('#c05a6c', { roughness: 0.8 }), corners.length);
    corners.forEach((c, i) => {
      m4.compose(new THREE.Vector3(c.x, H / 2, c.z), q.identity(), new THREE.Vector3(1, H, 1));
      poleMesh.setMatrixAt(i, m4);
      poles.push(c);
    });
    poleMesh.castShadow = true;
    scaffold.add(poleMesh);

    const levels = [1.35, Math.min(2.75, H - 0.4)];
    if (H > 4.4) levels.push(Math.min(4.15, H - 0.3));
    const plankGeo = new THREE.BoxGeometry(1, 0.08, 0.42);
    const plankMesh = new THREE.InstancedMesh(plankGeo, this.matFor('#c89060', { roughness: 0.9 }), (levels.length) * 4);
    let pi = 0;
    levels.forEach((y, li) => {
      // rails on all four sides
      const railLenW = scHalfW * 2, railLenD = scHalfD * 2;
      const railData = [
        { x: 0, z: -scHalfD, len: railLenW, rot: Math.PI / 2 },
        { x: 0, z: scHalfD, len: railLenW, rot: Math.PI / 2 },
        { x: -scHalfW, z: 0, len: railLenD, rot: 0 },
        { x: scHalfW, z: 0, len: railLenD, rot: 0 },
      ];
      for (const r of railData) {
        const rail = new THREE.Mesh(new THREE.BoxGeometry(r.len, 0.07, 0.07), this.matFor('#d77e8a', { roughness: 0.8 }));
        rail.position.set(r.x, y, r.z);
        rail.rotation.y = r.rot;
        scaffold.add(rail);
      }
      if (li < 3) {
        for (const side of [-1, 1]) {
          m4.compose(new THREE.Vector3(0, y - 0.09, side * scHalfD), q.identity(), new THREE.Vector3(def.w + 1.4, 1, 1));
          plankMesh.setMatrixAt(pi++, m4);
        }
        m4.compose(new THREE.Vector3(-scHalfW, y - 0.09, 0), q.identity(), new THREE.Vector3(1, 1, def.d + 1.4));
        plankMesh.setMatrixAt(pi++, m4);
      }
    });
    plankMesh.count = pi;
    plankMesh.castShadow = true;
    scaffold.add(plankMesh);
    g.add(scaffold);
    b.scaffold = scaffold;

    // --- construction sign ---
    const { canvas, ctx } = makeCanvas(512, 256);
    const tex = texFromCanvas(canvas);
    drawSignBoard(tex, ctx, canvas, def.name.toUpperCase(), `0 / ${b.slots.length} bricks`);
    const signGroup = new THREE.Group();
    signGroup.position.set(def.w / 2 + 1.4, 0, def.d / 2 + 2.6);
    addBox(signGroup, 0.12, 2.15, 0.12, '#9a7256', this.matFor, -1.15, 1.07, -0.08);
    addBox(signGroup, 0.12, 2.15, 0.12, '#9a7256', this.matFor, 1.15, 1.07, -0.08);
    const board = new THREE.Mesh(new THREE.PlaneGeometry(3.0, 1.5), new THREE.MeshBasicMaterial({ map: tex, transparent: true }));
    board.position.y = 1.75;
    signGroup.add(board);
    g.add(signGroup);
    b.signGroup = signGroup;
    b.sign = { canvas, ctx, texture: tex, board };

    // little stack of spare planks by the sign
    addBox(g, 1.4, 0.1, 0.5, '#c89060', this.matFor, def.w / 2 + 2.4, 0.1, def.d / 2 + 1.2, { rot: [0, 0.3, 0] });
  }

  updateSiteSign(b) {
    if (!b.sign || b.completed) return;
    const ctx = b.sign.ctx, canvas = b.sign.canvas;
    drawSignBoard(b.sign.texture, ctx, canvas, b.def.name.toUpperCase(), `${b.placedCount} / ${b.slots.length} bricks`);
    if (b.placedCount > 0) {
      // add a little green tick on the sign once work has started
      ctx.fillStyle = '#5fae7f';
      ctx.beginPath();
      ctx.arc(448, 44, 19, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = '#f8ecd7';
      ctx.lineWidth = 4;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(439, 44);
      ctx.lineTo(446, 51);
      ctx.lineTo(458, 36);
      ctx.stroke();
      b.sign.texture.needsUpdate = true;
    }
  }

  /* ============================================================
     Piles of loose bricks
     ============================================================ */
  buildPiles(b) {
    const counts = new Map();
    for (const s of b.slots) counts.set(s.key, (counts.get(s.key) || 0) + 1);
    const entries = [...counts.entries()].sort((a, c) => c[1] - a[1]);
    const def = b.def;
    const rng = makeRNG(5000 + b.index * 61);
    const spots = [];
    const cols = def.w > 8 ? 4 : 3;
    for (let row = 0; row < 3; row++) {
      for (let c = 0; c < cols; c++) {
        const x = -def.w / 2 - 0.4 + (def.w + 0.8) * ((c + 0.5) / cols);
        const z = def.d / 2 + 2.9 + row * 2.25;
        spots.push({ x, z });
      }
    }
    let spotIndex = 0;
    for (const [key, count] of entries) {
      const { piece } = this.keyToPiece(b, key);
      const heaps = Math.max(1, Math.ceil(count / 22));
      let remaining = count;
      for (let h = 0; h < heaps; h++) {
        const share = Math.min(remaining, Math.ceil(count / heaps));
        remaining -= share;
        const spot = spots[spotIndex++ % spots.length];
        const pileGroup = new THREE.Group();
        pileGroup.position.set(spot.x + (rng() - 0.5) * 0.5, 0, spot.z + (rng() - 0.5) * 0.35);
        b.group.add(pileGroup);

        const dirt = new THREE.Mesh(
          new THREE.CircleGeometry(1.32, 18),
          this.matFor('#c7a783', { roughness: 1 })
        );
        dirt.rotation.x = -Math.PI / 2;
        dirt.position.y = 0.045;
        dirt.receiveShadow = true;
        pileGroup.add(dirt);

        const mesh = new THREE.InstancedMesh(this.brickGeo, this.brickMat, share);
        mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        mesh.frustumCulled = false;
        const dims = BRICK_TYPES[piece.type].dims;
        const m4 = new THREE.Matrix4();
        const q = new THREE.Quaternion();
        const e = new THREE.Euler();
        const col = new THREE.Color();
        for (let i = 0; i < share; i++) {
          const layer = Math.floor(i / 8);
          const inLayer = i % 8;
          const a = inLayer * 2.399 + rng() * 0.5;
          const rad = layer === 0 ? 0.35 + rng() * 0.85 : 0.15 + rng() * 0.85;
          e.set((rng() - 0.5) * 0.35, rng() * TAU, (rng() - 0.5) * 0.28);
          q.setFromEuler(e);
          m4.compose(
            new THREE.Vector3(Math.cos(a) * rad, 0.19 + layer * 0.36 + rng() * 0.05, Math.sin(a) * rad),
            q,
            new THREE.Vector3(dims[0], dims[1], dims[2])
          );
          mesh.setMatrixAt(i, m4);
          col.set(piece.color);
          col.offsetHSL(0, 0, (rng() - 0.5) * 0.05);
          mesh.setColorAt(i, col);
        }
        mesh.instanceMatrix.needsUpdate = true;
        if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
        pileGroup.add(mesh);

        const signTex = makeSignTexture(BRICK_TYPES[piece.type].label, piece.name, {
          w: 384, h: 160, brickColor: piece.color, titleSize: 38, subSize: 23,
        });
        const label = new THREE.Mesh(
          new THREE.PlaneGeometry(2.05, 0.85),
          new THREE.MeshBasicMaterial({ map: signTex.texture, transparent: true })
        );
        label.position.set(0, 1.5, -1.18);
        pileGroup.add(label);
        addBox(pileGroup, 0.08, 1.35, 0.08, '#9a7256', this.matFor, -0.9, 0.67, -1.2);
        addBox(pileGroup, 0.08, 1.35, 0.08, '#9a7256', this.matFor, 0.9, 0.67, -1.2);

        const pile = {
          building: b, key, piece, group: pileGroup, mesh, stock: share,
          total: share, used: new Uint8Array(share), label, signTexture: signTex.texture,
        };
        mesh.userData = { type: 'pile', pile };
        b.piles.push(pile);
        this.piles.push(pile);
      }
    }
  }

  keyToPiece(b, key) {
    const slot = b.slots.find((s) => s.key === key);
    return { piece: slot.piece, slot };
  }

  hidePile(pile) {
    pile.group.visible = false;
  }

  /* ============================================================
     Interaction
     ============================================================ */
  collectRayTargets() {
    const targets = [];
    for (const b of this.buildings) {
      if (!b.completed) targets.push(b.ghost);
      for (const p of b.piles) if (p.group.visible && p.stock > 0) targets.push(p.mesh);
    }
    return targets;
  }

  pickPile(pile, instanceId) {
    if (!pile || pile.stock <= 0) return null;
    let idx = instanceId;
    if (idx == null || idx < 0 || idx >= pile.used.length || pile.used[idx]) {
      idx = pile.used.indexOf(0);
      if (idx < 0) return null;
    }
    pile.used[idx] = 1;
    pile.mesh.setMatrixAt(idx, HIDDEN);
    pile.mesh.instanceMatrix.needsUpdate = true;
    pile.stock--;
    if (pile.stock <= 0) this.hidePile(pile);
    return { key: pile.key, piece: pile.piece, pile, index: idx };
  }

  magnetPull(pos, radius, maxCount) {
    const found = [];
    const origin = new THREE.Vector3(pos.x, pos.y || 0, pos.z);
    const candidates = [];
    for (const p of this.piles) {
      if (!p.group.visible || p.stock <= 0) continue;
      const wp = new THREE.Vector3();
      p.group.getWorldPosition(wp);
      const d = wp.distanceTo(origin);
      if (d < radius) candidates.push({ pile: p, d, wp });
    }
    candidates.sort((a, b) => a.d - b.d);
    for (const c of candidates) {
      while (c.pile.stock > 0 && found.length < maxCount) {
        const idx = c.pile.used.indexOf(0);
        if (idx < 0) break;
        const res = this.pickPile(c.pile, idx);
        if (res) found.push({ ...res, worldPos: c.wp.clone() });
      }
      if (found.length >= maxCount) break;
    }
    return found;
  }

  resolveGhostHit(mesh, instanceId) {
    const b = mesh.userData.building;
    if (!b || b.completed) return null;
    const slot = b.slots[instanceId];
    if (!slot || slot.placed) return null;
    return { building: b, slot, index: instanceId };
  }

  countInventoryForBuilding(b, inv) {
    const totals = new Map();
    for (const s of b.slots) {
      if (!s.placed) totals.set(s.key, (totals.get(s.key) || 0) + 1);
    }
    let total = 0;
    for (const [k, v] of totals) total += v;
    return { missing: totals, total };
  }

  requirements(b) {
    const map = new Map();
    for (const s of b.slots) {
      if (!map.has(s.key)) {
        const info = keyInfo(s.key);
        map.set(s.key, { key: s.key, piece: s.piece, type: info.type, label: info.def.label, name: info.name, color: s.piece.color, count: 0, placed: 0 });
      }
      const e = map.get(s.key);
      e.count++;
      if (s.placed) e.placed++;
    }
    return [...map.values()].sort((a, c) => c.count - a.count);
  }

  /* ============================================================
     Placing bricks
     ============================================================ */
  placeSlot(b, index, opts = {}) {
    if (!b || b.completed) return null;
    const slot = b.slots[index];
    if (!slot || slot.placed) return null;
    slot.placed = true;
    b.placedCount++;
    b.ghost.setMatrixAt(index, HIDDEN);
    b.ghost.instanceMatrix.needsUpdate = true;
    b.placed.setMatrixAt(index, slot.localMatrix);
    b.placed.instanceMatrix.needsUpdate = true;
    b.pops.push({ index, t: 0 });
    this.updateSiteSign(b);
    if (this.onPlace) this.onPlace(b, slot);
    if (b.placedCount >= b.slots.length) this.finishBuilding(b, !opts.silent);
    return { building: b, slot, index };
  }

  finishBuilding(b, animate = true) {
    if (b.completed) return;
    b.completed = true;
    b.ghost.visible = false;
    if (b.scaffold) b.scaffold.visible = false;
    if (b.fence) b.fence.visible = false;
    if (b.signGroup) b.signGroup.visible = false;
    for (const p of b.piles) p.group.visible = false;
    b.decor = addBuildingDecor(this, b, animate);
    if (animate) b.decorPop = 0;
    if (this.onComplete) this.onComplete(b, animate);
  }

  /* ============================================================
     Active building marker
     ============================================================ */
  createMarker() {
    const g = new THREE.Group();
    g.visible = false;
    const beamMat = new THREE.MeshBasicMaterial({ color: '#ffd978', transparent: true, opacity: 0.12, depthWrite: false, blending: THREE.AdditiveBlending });
    const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.95, 11, 12, 1, true), beamMat);
    beam.position.y = 5.5;
    g.add(beam);

    const brickMat = new THREE.MeshStandardMaterial({ color: '#ffd15c', emissive: '#c98a22', emissiveIntensity: 0.8, roughness: 0.4, metalness: 0.1 });
    const brick = new THREE.Mesh(this.brickGeo, brickMat);
    brick.scale.set(1.6, 0.7, 0.62);
    brick.castShadow = false;
    g.add(brick);

    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(1.5, 0.06, 6, 24),
      new THREE.MeshBasicMaterial({ color: '#ffe9a8', transparent: true, opacity: 0.8, depthWrite: false })
    );
    ring.rotation.x = Math.PI / 2;
    g.add(ring);
    g.userData.brick = brick;
    g.userData.ring = ring;
    g.userData.beam = beam;

    // label sprite
    const { canvas, ctx } = makeCanvas(512, 128);
    const tex = texFromCanvas(canvas);
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false, depthWrite: false }));
    sprite.scale.set(6.2, 1.55, 1);
    sprite.position.y = 2.2;
    sprite.renderOrder = 20;
    g.add(sprite);
    g.userData.label = { canvas, ctx, tex };
    this.scene.add(g);
    return g;
  }

  updateMarkerLabel(b) {
    const { canvas, ctx, tex } = this.marker.userData.label;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'rgba(20,57,74,.93)';
    ctx.beginPath();
    ctx.roundRect(8, 12, 496, 104, 24);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,225,160,.5)';
    ctx.lineWidth = 3;
    ctx.stroke();
    ctx.fillStyle = '#ffe8ae';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = '600 46px Fredoka, "Trebuchet MS", sans-serif';
    ctx.fillText(b.def.name.toUpperCase(), 256, 52);
    ctx.fillStyle = 'rgba(255,247,229,.62)';
    ctx.font = '800 24px Nunito, "Segoe UI", sans-serif';
    ctx.fillText(`${b.placedCount} / ${b.slots.length} bricks`, 256, 91);
    tex.needsUpdate = true;
  }

  setFocus(id) {
    this.focusId = id;
    this.focusUntil = this.time + 6;
  }

  getActive(playerPos = null) {
    const incomplete = this.buildings.filter((b) => !b.completed);
    if (!incomplete.length) return null;
    if (this.focusId && this.time < this.focusUntil) {
      const f = this.getBuilding(this.focusId);
      if (f && !f.completed) return f;
    }
    if (playerPos) {
      let best = null, bestD = Infinity;
      for (const b of incomplete) {
        const d = Math.hypot(playerPos.x - b.x, playerPos.z - b.z);
        if (d < bestD) { bestD = d; best = b; }
      }
      if (best && bestD < 22) return best;
    }
    return incomplete.slice().sort((a, b) => a.def.order - b.def.order)[0];
  }

  update(dt, time, playerPos) {
    this.time = time;
    // brick pop animation
    for (const b of this.buildings) {
      if (!b.pops.length) continue;
      for (let i = b.pops.length - 1; i >= 0; i--) {
        const p = b.pops[i];
        p.t += dt;
        const k = Math.min(1, p.t / 0.3);
        const s = k < 1 ? easeOutBack(k) : 1;
        const slot = b.slots[p.index];
        const mat = new THREE.Matrix4().compose(
          slot.pos, slot.quat,
          new THREE.Vector3(slot.dims[0] * s, slot.dims[1] * s, slot.dims[2] * s)
        );
        b.placed.setMatrixAt(p.index, mat);
        b.placed.instanceMatrix.needsUpdate = true;
        if (k >= 1) b.pops.splice(i, 1);
      }
    }
    // decor pop
    for (const b of this.buildings) {
      if (b.decorPop >= 0 && b.decor) {
        b.decorPop += dt;
        const k = Math.min(1, b.decorPop / 0.55);
        const s = Math.max(0.001, easeOutBack(k));
        b.decor.scale.setScalar(s);
        if (k >= 1) b.decorPop = -1;
      }
    }
    // smoke puffs
    for (const s of this.smokeEmitters) {
      s.t += dt * s.speed;
      const k = (s.t % 1);
      s.mesh.position.y = s.baseY + k * 2.6;
      s.mesh.position.x = s.baseX + Math.sin(k * 5 + s.phase) * 0.22;
      s.mesh.scale.setScalar(0.4 + k * 0.75);
      s.mesh.material.opacity = 0.22 * (1 - k);
    }
    // clock hands
    if (this.clockHands.length) {
      const now = new Date();
      const min = now.getMinutes() + now.getSeconds() / 60;
      const hr = (now.getHours() % 12) + min / 60;
      for (const c of this.clockHands) {
        c.minute.rotation.z = -(min / 60) * TAU;
        c.hour.rotation.z = -(hr / 12) * TAU;
      }
    }

    const active = this.getActive(playerPos);
    this.active = active;
    this.activeId = active ? active.def.id : null;
    if (!active) {
      this.marker.visible = false;
      return;
    }
    const markerY = active.wallTop + active.def.roofRise + 3.1;
    this.marker.visible = true;
    this.marker.position.set(active.x, markerY + Math.sin(time * 1.8) * 0.22, active.z);
    this.marker.userData.brick.rotation.y += dt * 0.9;
    this.marker.userData.ring.rotation.z += dt * 0.55;
    this.marker.userData.beam.scale.y = 1 + Math.sin(time * 2) * 0.03;
    if (this.marker.userData.lastActive !== active.def.id) {
      this.marker.userData.lastActive = active.def.id;
      this.updateMarkerLabel(active);
    } else if (Math.floor(time * 4) % 8 === 0) {
      // keep the brick count fresh without redrawing every frame
      if (this.marker.userData.lastCount !== active.placedCount) {
        this.marker.userData.lastCount = active.placedCount;
        this.updateMarkerLabel(active);
      }
    }
  }

  /* ============================================================
     Collision, save & load
     ============================================================ */
  collides(x, z, radius) {
    for (const b of this.buildings) {
      if (!b.completed) continue;
      const dx = x - b.x, dz = z - b.z;
      const c = Math.cos(b.yaw), s = Math.sin(b.yaw);
      const lx = dx * c - dz * s;
      const lz = dx * s + dz * c;
      if (Math.abs(lx) < b.def.w / 2 + radius && Math.abs(lz) < b.def.d / 2 + radius) return true;
    }
    return false;
  }

  serialize() {
    const out = {};
    for (const b of this.buildings) {
      const placed = [];
      b.slots.forEach((s, i) => { if (s.placed) placed.push(i); });
      out[b.def.id] = placed;
    }
    return out;
  }

  applySave(data) {
    if (!data) return;
    for (const b of this.buildings) {
      const placed = data[b.def.id];
      if (!Array.isArray(placed)) continue;
      const set = new Set(placed);
      b.slots.forEach((s, i) => {
        if (set.has(i) && !s.placed) {
          s.placed = true;
          b.placedCount++;
          b.ghost.setMatrixAt(i, HIDDEN);
          b.placed.setMatrixAt(i, s.localMatrix);
        }
      });
      b.ghost.instanceMatrix.needsUpdate = true;
      b.placed.instanceMatrix.needsUpdate = true;
      this.updateSiteSign(b);
      if (b.placedCount >= b.slots.length) this.finishBuilding(b, false);
    }
  }

  getCompletionPercent() {
    return (this.totalPlaced / Math.max(1, this.totalBricks)) * 100;
  }
}

