86:       const q = quat ? quat.clone() : new THREE.Quaternion();
87:       const pos = new THREE.Vector3(x, y, z);
88:       const localMatrix = new THREE.Matrix4().compose(pos, q, new THREE.Vector3(dims[0], dims[1], dims[2]));
89:       slots.push({
90:         index: slots.length, piece: p, key: p.key, dims: [...dims], pos, quat: q,
91:         localMatrix, placed: false, color: p.color, meta,
92:       });
93:     };
94: 
95:     const wallTop = BASE_Y + def.rows * ROW_H;
96:     const halfW = def.w / 2, halfD = def.d / 2;
97:     const windows = [];
98:     const openingsFor = this.makeOpenings(def);
99: 
100:     // ---- wall courses ----
101:     const sides = [
102:       { name: 'front', axis: 'x', len: def.w, fixed: halfD - WALL_T / 2, sign: 1 },
103:       { name: 'back', axis: 'x', len: def.w, fixed: -halfD + WALL_T / 2, sign: -1 },
104:       { name: 'right', axis: 'z', len: def.d, fixed: halfW - WALL_T / 2, sign: 1 },
105:       { name: 'left', axis: 'z', len: def.d, fixed: -halfW + WALL_T / 2, sign: -1 },
106:     ];
107: 
108:     for (const side of sides) {
109:       const opens = openingsFor.filter((o) => o.side === side.name);
110:       const count = Math.max(2, Math.round(side.len / 1.36));
111:       const step = side.len / count;
112:       for (let row = 0; row < def.rows; row++) {
113:         const stagger = (row % 2) ? step * 0.5 : 0;
114:         for (let i = 0; i < count; i++) {
115:           let u = -side.len / 2 + step * (i + 0.5) + stagger;
116:           u = Math.max(-side.len / 2 + step / 2, Math.min(side.len / 2 - step / 2, u));
117:           let skip = false;
118:           for (const op of opens) {
119:             if (row >= op.row0 && row <= op.row1 && Math.abs(u - op.u) < op.w / 2 + step * 0.34) { skip = true; break; }
120:           }
121:           if (skip) continue;
122:           const brickLen = step - 0.035;
123:           const y = BASE_Y + row * ROW_H + ROW_H / 2;
124:           const isCorner = i === 0 || i === count - 1;
125:           let pid = 'wall';
126:           if (row === 0 || row === def.rows - 1 || isCorner) pid = 'trim';
127:           else if (row === 2 && (def.style === 'cottage' || def.style === 'bakery') && i % 4 === 0) pid = 'wallDeep';
128:           else if (rng() < 0.08) pid = 'wallDeep';
129:           if (def.style === 'greenhouse' && row > 0 && !isCorner && i % 3 === 1) pid = 'trim';
130:           const dims = side.axis === 'x'
131:             ? [brickLen, ROW_H - 0.04, WALL_T]
132:             : [WALL_T, ROW_H - 0.04, brickLen];
133:           const x = side.axis === 'x' ? u : side.fixed;
134:           const z = side.axis === 'x' ? side.fixed : u;
135:           add(pid, dims, x, y, z, null, { side: side.name, row });
136:         }
137:       }
138:     }
139: 
140:     // ---- windows as placeable slots ----
141:     for (const op of openingsFor) {
142:       if (op.type !== 'window') continue;
143:       const winH = (op.row1 - op.row0 + 1) * ROW_H - 0.1;
144:       const winW = Math.min(op.w, 1.65);
145:       const y = BASE_Y + ((op.row0 + op.row1 + 1) / 2) * ROW_H;
146:       const side = sides.find((s) => s.name === op.side);
147:       let dims, x, z;
148:       if (side.axis === 'x') {
149:         dims = [winW, winH, 0.3];
150:         x = op.u;
151:         z = side.fixed + (side.sign > 0 ? 0.03 : -0.03);
152:       } else {
153:         dims = [0.3, winH, winW];
154:         x = side.fixed + (side.sign > 0 ? 0.03 : -0.03);
155:         z = op.u;
156:       }
157:       add('glass', dims, x, y, z, null, { window: true, side: op.side });
158:       windows.push({ ...op, y, winH, winW, side });
159:     }
160: 
161:     // ---- gable ends ----
162:     if (def.roof !== 'flat') {
163:       const rise = def.roofRise;
164:       const G = Math.max(1, Math.round(rise / ROW_H));
165:       for (const side of [{ z: halfD - WALL_T / 2, name: 'front' }, { z: -halfD + WALL_T / 2, name: 'back' }]) {
166:         for (let g = 0; g < G; g++) {
167:           const y = wallTop + g * ROW_H + ROW_H / 2;
168:           const half = (def.w / 2) * (1 - g / G);
169:           const n = Math.max(1, Math.round((half * 2) / 1.36));
170:           const step = (half * 2) / n;
171:           for (let i = 0; i < n; i++) {
172:             const x = -half + step * (i + 0.5);
173:             let pid = 'wall';
174:             if (i === 0 || i === n - 1) pid = 'trim';
175:             else if (g === G - 1) pid = 'trim';
176:             add(pid, [step - 0.035, ROW_H - 0.04, WALL_T], x, y, side.z);
177:           }
178:         }
179:       }
180:     }
181: 
182:     // ---- roof ----
183:     const roofTop = def.roof === 'flat' ? wallTop + 0.25 : wallTop + def.roofRise;
184:     if (def.roof === 'flat') {
185:       for (let ix = 0; ix < 2; ix++) {
186:         for (let iz = 0; iz < 2; iz++) {
187:           add('roof', [def.w / 2 + 0.25, 0.36, def.d / 2 + 0.25], (ix - 0.5) * (def.w / 2 + 0.1), wallTop + 0.17, (iz - 0.5) * (def.d / 2 + 0.1));
188:         }
189:       }
190:     } else {
191:       const overX = 0.55, overZ = 0.6;
192:       const halfD2 = halfD + overZ;
193:       const rise = def.roadRise || def.roofRise;
194:       const angle = Math.atan2(rise, halfD2);
195:       const slopeLen = Math.hypot(rise, halfD2);
196:       const cols = def.w > 8 ? 3 : 2;
197:       const bw = (def.w + overX * 2) / cols;
198:       const rows = def.roofRows || 3;
199:       const roofPid = def.palette === 'greenhouse' ? 'roof' : 'roof';
200:       for (const side of [1, -1]) {
201:         for (let r = 0; r < rows; r++) {
202:           const f = (r + 0.5) / rows;
203:           const z = side * halfD2 * (1 - f);
204:           const y = wallTop + rise * f + 0.12;
205:           const segLen = slopeLen / rows + 0.14;
206:           const q = new THREE.Quaternion().setFromEuler(new THREE.Euler(side * angle, 0, 0));
207:           for (let c = 0; c < cols; c++) {
208:             const x = -def.w / 2 - overX + bw * (c + 0.5);
209:             let pid = roofPid;
210:             if (def.style === 'market' && (r + c) % 2 === 0 && pal.roofAlt) pid = 'roofAlt';
211:             add(pid, [bw - 0.04, 0.34, segLen], x, y, z, q, { roof: true });
212:           }
213:         }
214:       }
215:       add('roof', [def.w + overX * 2 + 0.1, 0.24, 0.55], 0, wallTop + rise + 0.22, 0, null, { roof: true, ridge: true });
216:     }
217: 
218:     return { slots, windows, wallTop, roofTop };
219:   }
220: 
221:   makeOpenings(def) {
222:     const list = [];
223:     const rows = def.rows;
224:     const winRows = rows >= 5 ? [2, 3] : [1, 2];
225:     const doorW = def.style === 'market' ? 2.35 : def.style === 'chapel' ? 1.75 : def.style === 'clocktower' ? 1.95 : 1.55;
226:     list.push({ side: 'front', u: 0, row0: 0, row1: 2, w: doorW, type: 'door' });
227:     const wx = def.w * 0.275;
228:     if (def.style === 'chapel') {
229:       list.push({ side: 'front', u: 0, row0: 3, row1: 4, w: 1.8, type: 'window' });
230:       list.push({ side: 'left', u: 0, row0: 1, row1: 3, w: 1.0, type: 'window' });
231:       list.push({ side: 'right', u: 0, row0: 1, row1: 3, w: 1.0, type: 'window' });
232:       return list;
233:     }
234:     if (def.style === 'clocktower') {
235:       list.push({ side: 'front', u: -wx, row0: 3, row1: 4, w: 1.1, type: 'window' });
236:       list.push({ side: 'front', u: wx, row0: 3, row1: 4, w: 1.1, type: 'window' });
237:       list.push({ side: 'left', u: -def.d * 0.2, row0: 2, row1: 3, w: 1.0, type: 'window' });
238:       list.push({ side: 'right', u: -def.d * 0.2, row0: 2, row1: 3, w: 1.0, type: 'window' });
239:       list.push({ side: 'back', u: -wx, row0: 2, row1: 3, w: 1.0, type: 'window' });
240:       list.push({ side: 'back', u: wx, row0: 2, row1: 3, w: 1.0, type: 'window' });
241:       return list;
242:     }
243:     if (def.style === 'greenhouse') {
244:       list.push({ side: 'front', u: -wx, row0: 1, row1: 2, w: 1.5, type: 'window' });
245:       list.push({ side: 'front', u: wx, row0: 1, row1: 2, w: 1.5, type: 'window' });
246:       list.push({ side: 'back', u: -wx, row0: 1, row1: 2, w: 1.5, type: 'window' });
247:       list.push({ side: 'back', u: wx, row0: 1, row1: 2, w: 1.5, type: 'window' });
248:       list.push({ side: 'left', u: -def.d * 0.2, row0: 1, row1: 2, w: 1.3, type: 'window' });
249:       list.push({ side: 'left', u: def.d * 0.2, row0: 1, row1: 2, w: 1.3, type: 'window' });
250:       list.push({ side: 'right', u: -def.d * 0.2, row0: 1, row1: 2, w: 1.3, type: 'window' });
251:       list.push({ side: 'right', u: def.d * 0.2, row0: 1, row1: 2, w: 1.3, type: 'window' });
252:       return list;
253:     }
254:     if (def.style === 'market') {
255:       list.push({ side: 'front', u: -wx, row0: 1, row1: 2, w: 1.2, type: 'window' });
256:       list.push({ side: 'front', u: wx, row0: 1, row1: 2, w: 1.2, type: 'window' });
257:       list.push({ side: 'back', u: -wx, row0: 1, row1: 2, w: 1.1, type: 'window' });
258:       list.push({ side: 'back', u: wx, row0: 1, row1: 2, w: 1.1, type: 'window' });
259:       list.push({ side: 'left', u: 0, row0: 1, row1: 2, w: 1.0, type: 'window' });
260:       list.push({ side: 'right', u: 0, row0: 1, row1: 2, w: 1.0, type: 'window' });
261:       return list;
262:     }
263:     // standard cottage-ish building
264:     list.push({ side: 'front', u: -wx, row0: winRows[0], row1: winRows[1], w: 1.1, type: 'window' });
265:     list.push({ side: 'front', u: wx, row0: winRows[0], row1: winRows[1], w: 1.1, type: 'window' });
266:     list.push({ side: 'back', u: -wx, row0: winRows[0], row1: winRows[1], w: 1.0, type: 'window' });
267:     list.push({ side: 'back', u: wx, row0: winRows[0], row1: winRows[1], w: 1.0, type: 'window' });
268:     list.push({ side: 'left', u: 0, row0: winRows[0], row1: winRows[1], w: 1.0, type: 'window' });
269:     list.push({ side: 'right', u: 0, row0: winRows[0], row1: winRows[1], w: 1.0, type: 'window' });
270:     return list;
271:   }
