276:   createBuilding(def, index) {
277:     const rng = makeRNG(9001 + index * 331);
278:     const pos = buildingWorldPosition(def);
279:     const group = new THREE.Group();
280:     group.position.set(pos.x, 0, pos.z);
281:     group.rotation.y = buildingYaw(def);
282:     group.name = `building-${def.id}`;
283:     this.scene.add(group);
284: 
285:     const { slots, windows, wallTop, roofTop } = this.generateSlots(def, index);
286:     const b = {
287:       def, index, group, slots, windows, wallTop, roofTop,
288:       placedCount: 0, completed: false, pops: [], decor: null, decorPop: -1,
289:       x: pos.x, z: pos.z, yaw: group.rotation.y,
290:       sign: null, scaffold: null, fence: null, signGroup: null, piles: [],
291:       total: slots.length,
292:     };
293: 
294:     const ghost = new THREE.InstancedMesh(this.brickGeo, this.ghostMat, slots.length);
295:     ghost.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
296:     ghost.frustumCulled = false;
297:     ghost.castShadow = false;
298:     ghost.receiveShadow = false;
299:     ghost.userData = { type: 'ghost', building: b };
300:     const placed = new THREE.InstancedMesh(this.brickGeo, this.brickMat, slots.length);
301:     placed.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
302:     placed.frustumCulled = false;
303:     placed.castShadow = true;
304:     placed.receiveShadow = true;
305:     placed.userData = { type: 'placed', building: b };
306: 
307:     const color = new THREE.Color();
308:     slots.forEach((slot, i) => {
309:       ghost.setMatrixAt(i, slot.localMatrix);
310:       placed.setMatrixAt(i, HIDDEN);
311:       color.set(slot.piece.color);
312:       color.offsetHSL((rng() - 0.5) * 0.008, (rng() - 0.5) * 0.035, (rng() - 0.5) * 0.038);
313:       slot.instanceColor = color.clone();
314:       placed.setColorAt(i, slot.instanceColor);
315:     });
316:     ghost.instanceMatrix.needsUpdate = true;
317:     placed.instanceMatrix.needsUpdate = true;
318:     placed.instanceColor.needsUpdate = true;
319:     group.add(ghost, placed);
320:     b.ghost = ghost;
321:     b.placed = placed;
322: 
323:     this.buildFoundation(b);
324:     this.buildSite(b);
325:     this.buildPiles(b);
326:     this.buildings.push(b);
327:     return b;
328:   }
