330:   buildFoundation(b) {
331:     const def = b.def;
332:     const pal = PALETTES[def.palette];
333:     const g = b.group;
334:     // stone site pad
335:     const pad = new THREE.Mesh(
336:       new THREE.BoxGeometry(def.w + 3.2, 0.14, def.d + 3.2),
337:       this.matFor('#d9c3a5', { roughness: 1 })
338:     );
339:     pad.position.y = 0.07;
340:     pad.receiveShadow = true;
341:     pad.castShadow = true;
342:     g.add(pad);
343:     // foundation
344:     addBox(g, def.w + 0.7, BASE_Y, def.d + 0.7, pal.base.color, this.matFor, 0, BASE_Y / 2, 0, { roughness: 1 });
345:     addBox(g, def.w + 1.0, 0.14, def.d + 1.0, '#b79b9b', this.matFor, 0, BASE_Y + 0.02, 0, { roughness: 1 });
346:     // steps
347:     addBox(g, 2.0, 0.16, 0.6, '#d8c2a6', this.matFor, 0, 0.08, def.d / 2 + 0.72, { roughness: 1 });
348:     addBox(g, 1.75, 0.3, 0.45, '#cdb49a', this.matFor, 0, 0.15, def.d / 2 + 0.5, { roughness: 1 });
349:     // dark doorway recess
350:     addBox(g, 1.42, 2.08, 0.12, '#443744', this.matFor, 0, BASE_Y + 1.04, def.d / 2 - 0.22, { roughness: 1 });
351:     // door frame
352:     const trim = PALETTES[def.palette].trim.color;
353:     addBox(g, 0.18, 2.35, 0.16, trim, this.matFor, -0.82, BASE_Y + 1.18, def.d / 2 + 0.01);
354:     addBox(g, 0.18, 2.35, 0.16, trim, this.matFor, 0.82, BASE_Y + 1.18, def.d / 2 + 0.01);
355:     addBox(g, 1.82, 0.2, 0.16, trim, this.matFor, 0, BASE_Y + 2.26, def.d / 2 + 0.01);
356: 
357:     // window frames around the openings
358:     const sideInfo = {
359:       front: { axis: 'x', fixed: def.d / 2 },
360:       back: { axis: 'x', fixed: -def.d / 2 },
361:       left: { axis: 'z', fixed: -def.w / 2 },
362:       right: { axis: 'z', fixed: def.w / 2 },
363:     };
364:     for (const w of b.windows) {
365:       const info = sideInfo[w.side];
366:       const cy = w.y;
367:       const h = w.winH;
368:       const ww = w.winW;
369:       const frameCol = def.palette === 'greenhouse' ? '#f1e6cf' : trim;
370:       if (info.axis === 'x') {
371:         const z = info.fixed + (info.fixed > 0 ? 0.03 : -0.03);
372:         addBox(g, 0.13, h + 0.24, 0.16, frameCol, this.matFor, w.u - ww / 2 - 0.05, cy, z);
373:         addBox(g, 0.13, h + 0.24, 0.16, frameCol, this.matFor, w.u + ww / 2 + 0.05, cy, z);
374:         addBox(g, ww + 0.24, 0.14, 0.18, frameCol, this.matFor, w.u, cy + h / 2 + 0.06, z);
375:         addBox(g, ww + 0.24, 0.14, 0.2, frameCol, this.matFor, w.u, cy - h / 2 - 0.06, z);
376:         addBox(g, ww + 0.36, 0.11, 0.32, '#cdb49a', this.matFor, w.u, cy - h / 2 - 0.18, z + (z > 0 ? 0.06 : -0.06), { roughness: 1 });
377:       } else {
378:         const x = info.fixed + (info.fixed > 0 ? 0.03 : -0.03);
379:         addBox(g, 0.16, h + 0.24, 0.13, frameCol, this.matFor, x, cy, w.u - ww / 2 - 0.05);
380:         addBox(g, 0.16, h + 0.24, 0.13, frameCol, this.matFor, x, cy, w.u + ww / 2 + 0.05);
381:         addBox(g, 0.18, 0.14, ww + 0.24, frameCol, this.matFor, x, cy + h / 2 + 0.06, w.u);
382:         addBox(g, 0.2, 0.14, ww + 0.24, frameCol, this.matFor, x, cy - h / 2 - 0.06, w.u);
383:         addBox(g, 0.32, 0.11, ww + 0.36, '#cdb49a', this.matFor, x + (x > 0 ? 0.06 : -0.06), cy - h / 2 - 0.18, w.u, { roughness: 1 });
384:       }
385:     }
386: 
387:     // loose construction rubble
388:     for (let i = 0; i < 7; i++) {
389:       const rubble = new THREE.Mesh(this.brickGeo, this.matFor(i % 2 ? pal.base.color : '#cfb6aa', { roughness: 0.9 }));
390:       rubble.scale.set(0.5 + Math.random() * 0.3, 0.28, 0.22);
391:       rubble.position.set((Math.random() - 0.5) * (def.w + 2.2), 0.14, (Math.random() - 0.5) * 2 + def.d / 2 + 1.6);
392:       rubble.rotation.set(Math.random() * 0.4 - 0.2, Math.random() * TAU, 0);
393:       rubble.castShadow = true;
394:       g.add(rubble);
395:     }
396:   }
