398:   /* ---------------- scaffolding, fencing, sign ---------------- */
399:   buildSite(b) {
400:     const def = b.def;
401:     const g = b.group;
402:     const halfW = def.w / 2 + 1.8;
403:     const halfD = def.d / 2 + 1.8;
404: 
405:     // --- low construction fence ---
406:     const posts = [];
407:     const rails = [];
408:     const pushSide = (x1, z1, x2, z2) => {
409:       const len = Math.hypot(x2 - x1, z2 - z1);
410:       const n = Math.max(2, Math.ceil(len / 1.45));
411:       const rot = Math.atan2(x2 - x1, z2 - z1);
412:       for (let i = 0; i <= n; i++) {
413:         const t = i / n;
414:         posts.push({ x: x1 + (x2 - x1) * t, z: z1 + (z2 - z1) * t });
415:       }
416:       for (let i = 0; i < n; i++) {
417:         const t0 = i / n, t1 = (i + 1) / n;
418:         const cx = x1 + (x2 - x1) * (t0 + t1) / 2;
419:         const cz = z1 + (z2 - z1) * (t0 + t1) / 2;
420:         rails.push({ x: cx, z: cz, len: len / n, rot });
421:       }
422:     };
423:     pushSide(-halfW, -halfD, halfW, -halfD); // back
424:     pushSide(-halfW, -halfD, -halfW, halfD); // left
425:     pushSide(halfW, -halfD, halfW, halfD); // right
426:     pushSide(-halfW, halfD, -1.5, halfD); // front left
427:     pushSide(1.5, halfD, halfW, halfD); // front right
428: 
429:     const fenceGroup = new THREE.Group();
430:     const postGeo = new THREE.BoxGeometry(0.12, 0.98, 0.12);
431:     const railGeo = new THREE.BoxGeometry(1, 0.1, 0.07);
432:     const postMesh = new THREE.InstancedMesh(postGeo, this.matFor('#c35e70', { roughness: 0.85 }), posts.length);
433:     const railMesh = new THREE.InstancedMesh(railGeo, this.matFor('#d58a74', { roughness: 0.85 }), rails.length * 2);
434:     const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), e = new THREE.Euler();
435:     posts.forEach((p, i) => {
436:       m4.compose(new THREE.Vector3(p.x, 0.49, p.z), q.identity(), new THREE.Vector3(1, 1, 1));
437:       postMesh.setMatrixAt(i, m4);
438:     });
439:     rails.forEach((r, i) => {
440:       e.set(0, r.rot + Math.PI / 2, 0); q.setFromEuler(e);
441:       m4.compose(new THREE.Vector3(r.x, 0.4, r.z), q, new THREE.Vector3(r.len, 1, 1));
442:       railMesh.setMatrixAt(i * 2, m4);
443:       m4.compose(new THREE.Vector3(r.x, 0.76, r.z), q, new THREE.Vector3(r.len, 1, 1));
444:       railMesh.setMatrixAt(i * 2 + 1, m4);
445:     });
446:     postMesh.castShadow = true; railMesh.castShadow = true;
447:     fenceGroup.add(postMesh, railMesh);
448:     g.add(fenceGroup);
449:     b.fence = fenceGroup;
450: 
451:     // --- scaffolding ---
452:     const scaffold = new THREE.Group();
453:     const poleGeo = new THREE.CylinderGeometry(0.055, 0.065, 1, 6);
454:     const poles = [];
455:     const scHalfW = def.w / 2 + 0.65, scHalfD = def.d / 2 + 0.65;
456:     const H = Math.min(b.wallTop + def.roofRise * 0.35, 7.2);
457:     const corners = [];
458:     for (const x of [-scHalfW, scHalfW]) for (const z of [-scHalfD, scHalfD]) corners.push({ x, z });
459:     for (const x of [0]) for (const z of [-scHalfD, scHalfD]) corners.push({ x, z });
460:     for (const z of [0]) for (const x of [-scHalfW, scHalfW]) corners.push({ x, z });
461:     const poleMesh = new THREE.InstancedMesh(poleGeo, this.matFor('#c05a6c', { roughness: 0.8 }), corners.length);
462:     corners.forEach((c, i) => {
463:       m4.compose(new THREE.Vector3(c.x, H / 2, c.z), q.identity(), new THREE.Vector3(1, H, 1));
464:       poleMesh.setMatrixAt(i, m4);
465:       poles.push(c);
466:     });
467:     poleMesh.castShadow = true;
468:     scaffold.add(poleMesh);
469: 
470:     const levels = [1.35, Math.min(2.75, H - 0.4)];
471:     if (H > 4.4) levels.push(Math.min(4.15, H - 0.3));
472:     const plankGeo = new THREE.BoxGeometry(1, 0.08, 0.42);
473:     const plankMesh = new THREE.InstancedMesh(plankGeo, this.matFor('#c89060', { roughness: 0.9 }), (levels.length) * 4);
474:     let pi = 0;
475:     levels.forEach((y, li) => {
476:       // rails on all four sides
477:       const railLenW = scHalfW * 2, railLenD = scHalfD * 2;
478:       const railData = [
479:         { x: 0, z: -scHalfD, len: railLenW, rot: Math.PI / 2 },
480:         { x: 0, z: scHalfD, len: railLenW, rot: Math.PI / 2 },
481:         { x: -scHalfW, z: 0, len: railLenD, rot: 0 },
482:         { x: scHalfW, z: 0, len: railLenD, rot: 0 },
483:       ];
484:       for (const r of railData) {
485:         const rail = new THREE.Mesh(new THREE.BoxGeometry(r.len, 0.07, 0.07), this.matFor('#d77e8a', { roughness: 0.8 }));
486:         rail.position.set(r.x, y, r.z);
487:         rail.rotation.y = r.rot;
488:         scaffold.add(rail);
489:       }
490:       if (li < 3) {
491:         for (const side of [-1, 1]) {
492:           m4.compose(new THREE.Vector3(0, y - 0.09, side * scHalfD), q.identity(), new THREE.Vector3(def.w + 1.4, 1, 1));
493:           plankMesh.setMatrixAt(pi++, m4);
494:         }
495:         m4.compose(new THREE.Vector3(-scHalfW, y - 0.09, 0), q.identity(), new THREE.Vector3(1, 1, def.d + 1.4));
496:         plankMesh.setMatrixAt(pi++, m4);
497:       }
498:     });
499:     plankMesh.count = pi;
500:     plankMesh.castShadow = true;
501:     scaffold.add(plankMesh);
502:     g.add(scaffold);
503:     b.scaffold = scaffold;
