508:     drawSignBoard(tex, ctx, canvas, def.name.toUpperCase(), `0 / ${b.slots.length} bricks`);
509:     const signGroup = new THREE.Group();
510:     signGroup.position.set(def.w / 2 + 1.4, 0, def.d / 2 + 2.6);
511:     addBox(signGroup, 0.12, 2.15, 0.12, '#9a7256', this.matFor, -1.15, 1.07, -0.08);
512:     addBox(signGroup, 0.12, 2.15, 0.12, '#9a7256', this.matFor, 1.15, 1.07, -0.08);
513:     const board = new THREE.Mesh(new THREE.PlaneGeometry(3.0, 1.5), new THREE.MeshBasicMaterial({ map: tex, transparent: true }));
514:     board.position.y = 1.75;
515:     signGroup.add(board);
516:     g.add(signGroup);
