546:   /* ============================================================
547:      Piles of loose bricks
548:      ============================================================ */
549:   buildPiles(b) {
550:     const counts = new Map();
551:     for (const s of b.slots) counts.set(s.key, (counts.get(s.key) || 0) + 1);
552:     const entries = [...counts.entries()].sort((a, c) => c[1] - a[1]);
553:     const def = b.def;
554:     const rng = makeRNG(5000 + b.index * 61);
555:     const spots = [];
556:     const cols = def.w > 8 ? 4 : 3;
557:     for (let row = 0; row < 3; row++) {
558:       for (let c = 0; c < cols; c++) {
559:         const x = -def.w / 2 - 0.4 + (def.w + 0.8) * ((c + 0.5) / cols);
560:         const z = def.d / 2 + 2.9 + row * 2.25;
561:         spots.push({ x, z });
562:       }
563:     }
564:     let spotIndex = 0;
565:     for (const [key, count] of entries) {
566:       const { piece } = this.keyToPiece(b, key);
567:       const heaps = Math.max(1, Math.ceil(count / 22));
568:       let remaining = count;
569:       for (let h = 0; h < heaps; h++) {
570:         const share = Math.min(remaining, Math.ceil(count / heaps));
571:         remaining -= share;
572:         const spot = spots[spotIndex++ % spots.length];
573:         const pileGroup = new THREE.Group();
574:         pileGroup.position.set(spot.x + (rng() - 0.5) * 0.5, 0, spot.z + (rng() - 0.5) * 0.35);
575:         b.group.add(pileGroup);
576: 
577:         const dirt = new THREE.Mesh(
578:           new THREE.CircleGeometry(1.32, 18),
579:           this.matFor('#c7a783', { roughness: 1 })
580:         );
581:         dirt.rotation.x = -Math.PI / 2;
582:         dirt.position.y = 0.045;
583:         dirt.receiveShadow = true;
584:         pileGroup.add(dirt);
585: 
586:         const mesh = new THREE.InstancedMesh(this.brickGeo, this.brickMat, share);
587:         mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
588:         mesh.castShadow = true;
589:         mesh.receiveShadow = true;
590:         mesh.frustumCulled = false;
591:         const dims = BRICK_TYPES[piece.type].dims;
592:         const m4 = new THREE.Matrix4();
593:         const q = new THREE.Quaternion();
594:         const e = new THREE.Euler();
595:         const col = new THREE.Color();
596:         for (let i = 0; i < share; i++) {
597:           const layer = Math.floor(i / 8);
598:           const inLayer = i % 8;
599:           const a = inLayer * 2.399 + rng() * 0.5;
600:           const rad = layer === 0 ? 0.35 + rng() * 0.85 : 0.15 + rng() * 0.85;
601:           e.set((rng() - 0.5) * 0.35, rng() * TAU, (rng() - 0.5) * 0.28);
602:           q.setFromEuler(e);
603:           m4.compose(
604:             new THREE.Vector3(Math.cos(a) * rad, 0.19 + layer * 0.36 + rng() * 0.05, Math.sin(a) * rad),
605:             q,
606:             new THREE.Vector3(dims[0], dims[1], dims[2])
607:           );
608:           mesh.setMatrixAt(i, m4);
609:           col.set(piece.color);
610:           col.offsetHSL(0, 0, (rng() - 0.5) * 0.05);
611:           mesh.setColorAt(i, col);
612:         }
613:         mesh.instanceMatrix.needsUpdate = true;
614:         if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
615:         pileGroup.add(mesh);
616: 
617:         const signTex = makeSignTexture(BRICK_TYPES[piece.type].label, piece.name, {
618:           w: 384, h: 160, brickColor: piece.color, titleSize: 38, subSize: 23,
619:         });
620:         const label = new THREE.Mesh(
621:           new THREE.PlaneGeometry(2.05, 0.85),
622:           new THREE.MeshBasicMaterial({ map: signTex.texture, transparent: true })
623:         );
624:         label.position.set(0, 1.5, -1.18);
625:         pileGroup.add(label);
626:         addBox(pileGroup, 0.08, 1.35, 0.08, '#9a7256', this.matFor, -0.9, 0.67, -1.2);
627:         addBox(pileGroup, 0.08, 1.35, 0.08, '#9a7256', this.matFor, 0.9, 0.67, -1.2);
628: 
629:         const pile = {
630:           building: b, key, piece, group: pileGroup, mesh, stock: share,
631:           total: share, used: new Uint8Array(share), label, signTexture: signTex.texture,
632:         };
633:         mesh.userData = { type: 'pile', pile };
634:         b.piles.push(pile);
635:         this.piles.push(pile);
636:       }
637:     }
638:   }
