652:   collectRayTargets() {
653:     const targets = [];
654:     for (const b of this.buildings) {
655:       if (!b.completed) targets.push(b.ghost);
656:       for (const p of b.piles) if (p.group.visible && p.stock > 0) targets.push(p.mesh);
