661:   pickPile(pile, instanceId) {
662:     if (!pile || pile.stock <= 0) return null;
663:     let idx = instanceId;
664:     if (idx == null || idx < 0 || idx >= pile.used.length || pile.used[idx]) {
665:       idx = pile.used.indexOf(0);
666:       if (idx < 0) return null;
667:     }
668:     pile.used[idx] = 1;
669:     pile.mesh.setMatrixAt(idx, HIDDEN);
670:     pile.mesh.instanceMatrix.needsUpdate = true;
671:     pile.stock--;
672:     if (pile.stock <= 0) this.hidePile(pile);
673:     return { key: pile.key, piece: pile.piece, pile, index: idx };
674:   }
