676:   magnetPull(pos, radius, maxCount) {
677:     const found = [];
678:     const origin = new THREE.Vector3(pos.x, pos.y || 0, pos.z);
679:     const candidates = [];
680:     for (const p of this.piles) {
681:       if (!p.group.visible || p.stock <= 0) continue;
682:       const wp = new THREE.Vector3();
683:       p.group.getWorldPosition(wp);
684:       const d = wp.distanceTo(origin);
685:       if (d < radius) candidates.push({ pile: p, d, wp });
686:     }
687:     candidates.sort((a, b) => a.d - b.d);
688:     for (const c of candidates) {
689:       while (c.pile.stock > 0 && found.length < maxCount) {
690:         const idx = c.pile.used.indexOf(0);
691:         if (idx < 0) break;
692:         const res = this.pickPile(c.pile, idx);
693:         if (res) found.push({ ...res, worldPos: c.wp.clone() });
694:       }
695:       if (found.length >= maxCount) break;
696:     }
697:     return found;
698:   }
