745:     b.pops.push({ index, t: 0 });
746:     this.updateSiteSign(b);
747:     if (this.onPlace) this.onPlace(b, slot);
748:     if (b.placedCount >= b.slots.length) this.finishBuilding(b, !opts.silent);
749:     return { building: b, slot, index };
