831:   getActive(playerPos = null) {
832:     const incomplete = this.buildings.filter((b) => !b.completed);
833:     if (!incomplete.length) return null;
834:     if (this.focusId && this.time < this.focusUntil) {
835:       const f = this.getBuilding(this.focusId);
836:       if (f && !f.completed) return f;
837:     }
838:     if (playerPos) {
839:       let best = null, bestD = Infinity;
840:       for (const b of incomplete) {
841:         const d = Math.hypot(playerPos.x - b.x, playerPos.z - b.z);
842:         if (d < bestD) { bestD = d; best = b; }
843:       }
844:       if (best && bestD < 22) return best;
845:     }
846:     return incomplete.slice().sort((a, b) => a.def.order - b.def.order)[0];
847:   }
