849:   update(dt, time, playerPos) {
850:     this.time = time;
851:     // brick pop animation
852:     for (const b of this.buildings) {
853:       if (!b.pops.length) continue;
854:       for (let i = b.pops.length - 1; i >= 0; i--) {
855:         const p = b.pops[i];
856:         p.t += dt;
857:         const k = Math.min(1, p.t / 0.3);
858:         const s = k < 1 ? easeOutBack(k) : 1;
859:         const slot = b.slots[p.index];
860:         const mat = new THREE.Matrix4().compose(
861:           slot.pos, slot.quat,
862:           new THREE.Vector3(slot.dims[0] * s, slot.dims[1] * s, slot.dims[2] * s)
863:         );
864:         b.placed.setMatrixAt(p.index, mat);
865:         b.placed.instanceMatrix.needsUpdate = true;
866:         if (k >= 1) b.pops.splice(i, 1);
867:       }
868:     }
869:     // decor pop
870:     for (const b of this.buildings) {
871:       if (b.decorPop >= 0 && b.decor) {
872:         b.decorPop += dt;
873:         const k = Math.min(1, b.decorPop / 0.55);
874:         const s = Math.max(0.001, easeOutBack(k));
875:         b.decor.scale.setScalar(s);
876:         if (k >= 1) b.decorPop = -1;
877:       }
878:     }
879:     // smoke puffs
880:     for (const s of this.smokeEmitters) {
881:       s.t += dt * s.speed;
882:       const k = (s.t % 1);
883:       s.mesh.position.y = s.baseY + k * 2.6;
884:       s.mesh.position.x = s.baseX + Math.sin(k * 5 + s.phase) * 0.22;
885:       s.mesh.scale.setScalar(0.4 + k * 0.75);
886:       s.mesh.material.opacity = 0.22 * (1 - k);
887:     }
888:     // clock hands
889:     if (this.clockHands.length) {
890:       const now = new Date();
891:       const min = now.getMinutes() + now.getSeconds() / 60;
892:       const hr = (now.getHours() % 12) + min / 60;
893:       for (const c of this.clockHands) {
894:         c.minute.rotation.z = -(min / 60) * TAU;
895:         c.hour.rotation.z = -(hr / 12) * TAU;
896:       }
897:     }
898: 
899:     const active = this.getActive(playerPos);
900:     this.active = active;
901:     this.activeId = active ? active.def.id : null;
902:     if (!active) {
903:       this.marker.visible = false;
904:       return;
905:     }
906:     const markerY = active.wallTop + active.def.roofRise + 3.1;
907:     this.marker.visible = true;
908:     this.marker.position.set(active.x, markerY + Math.sin(time * 1.8) * 0.22, active.z);
909:     this.marker.userData.brick.rotation.y += dt * 0.9;
910:     this.marker.userData.ring.rotation.z += dt * 0.55;
911:     this.marker.userData.beam.scale.y = 1 + Math.sin(time * 2) * 0.03;
912:     if (this.marker.userData.lastActive !== active.def.id) {
913:       this.marker.userData.lastActive = active.def.id;
914:       this.updateMarkerLabel(active);
915:     } else if (Math.floor(time * 4) % 8 === 0) {
916:       // keep the brick count fresh without redrawing every frame
917:       if (this.marker.userData.lastCount !== active.placedCount) {
918:         this.marker.userData.lastCount = active.placedCount;
919:         this.updateMarkerLabel(active);
920:       }
921:     }
922:   }
