924:   /* ============================================================
925:      Collision, save & load
926:      ============================================================ */
927:   collides(x, z, radius) {
928:     for (const b of this.buildings) {
929:       if (!b.completed) continue;
930:       const dx = x - b.x, dz = z - b.z;
931:       const c = Math.cos(b.yaw), s = Math.sin(b.yaw);
932:       const lx = dx * c - dz * s;
933:       const lz = dx * s + dz * c;
934:       if (Math.abs(lx) < b.def.w / 2 + radius && Math.abs(lz) < b.def.d / 2 + radius) return true;
935:     }
936:     return false;
937:   }
