730:   /* ---------------- update ---------------- */
731:   update(dt, time) {
732:     this.time = time;
733:     // fountain water
734:     if (this.fountainParticles) {
735:       const p = this.fountainParticles;
736:       for (let i = 0; i < p.count; i++) {
737:         const ix = i * 3;
738:         p.positions[ix] += p.vel[i].x * dt;
739:         p.positions[ix + 1] += p.vel[i].y * dt;
740:         p.positions[ix + 2] += p.vel[i].z * dt;
741:         p.vel[i].y -= 3.6 * dt;
742:         if (p.positions[ix + 1] < 0.72) {
743:           p.positions[ix] = 0; p.positions[ix + 1] = 2.75; p.positions[ix + 2] = 0;
744:           const a = Math.random() * TAU, sp = 0.35 + Math.random() * 0.9;
745:           p.vel[i].x = Math.cos(a) * sp * 0.35;
746:           p.vel[i].y = 1.2 + Math.random() * 1.1;
747:           p.vel[i].z = Math.sin(a) * sp * 0.35;
748:         }
749:       }
750:       p.points.geometry.attributes.position.needsUpdate = true;
751:     }
752:     if (this.fountainWater) this.fountainWater.rotation.y += dt * 0.07;
753: 
754:     for (const cloud of this.clouds) {
755:       cloud.position.x += cloud.userData.speed * dt;
756:       if (cloud.position.x > 135) cloud.position.x = -135;
757:     }
758: 
759:     for (const bird of this.birds) {
760:       const u = bird.userData;
761:       u.phase += dt * u.speed;
762:       bird.position.set(Math.cos(u.phase) * u.radius, u.height + Math.sin(u.phase * 3) * 0.5, Math.sin(u.phase) * u.radius);
763:       bird.rotation.y = -u.phase + Math.PI / 2;
764:       const flap = Math.sin(time * 7 + u.phase * 6) * 0.55;
765:       u.left.rotation.z = flap;
766:       u.right.rotation.z = -flap;
767:     }
768:   }
